@import url("https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;700;800&family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,500,0,0&family=Nunito:wght@500;600;700;800&display=swap");

* { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --hmis-primary: #13d802;
  --hmis-accent: #0a7f48;
  --hmis-highlight: #f1c40f;
  --hmis-text: #111827;
  --hmis-surface: #ffffff;
  --hmis-bg: #f2f4f7;
  --hmis-border: #dbe4ee;
  --hmis-sidebar-start: #050709;
  --hmis-sidebar-mid: #0a0b0d;
  --hmis-sidebar-end: #111417;
  --hmis-selected-bg: #d7fbe9;
  --app-text-color: #0f172a;
  --app-font-family: "Nunito", system-ui, -apple-system, sans-serif;
  --font-primary: var(--app-font-family);
}

body {
  font-family: var(--app-font-family);
  background: linear-gradient(180deg, var(--hmis-bg) 0%, #eef2f7 100%);
  height: 100vh;
  overflow: hidden;
}

/* ─── UPDATER BANNER ─── */
.hmis-update-banner {
  position: fixed;
  right: 18px;
  top: 18px;
  z-index: 9999;
  width: min(520px, calc(100vw - 36px));
  background: rgba(17, 24, 39, 0.92);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: rgba(255, 255, 255, 0.92);
  border-radius: 16px;
  padding: 14px 14px;
  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.25);
  backdrop-filter: blur(10px);
}

.hmis-update-banner__title {
  font-weight: 800;
  font-size: 14px;
  letter-spacing: 0.2px;
}

.hmis-update-banner__message {
  margin-top: 6px;
  font-size: 12px;
  line-height: 1.35;
  color: rgba(255, 255, 255, 0.74);
}

.hmis-update-banner__actions {
  display: flex;
  gap: 10px;
  margin-top: 12px;
  justify-content: flex-end;
  flex-wrap: wrap;
}

.hmis-update-banner__btn {
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.9);
  padding: 8px 12px;
  font-weight: 700;
  font-size: 12px;
  cursor: pointer;
}

.hmis-update-banner__btn.primary {
  background: rgba(19, 216, 2, 0.16);
  border-color: rgba(19, 216, 2, 0.45);
}

.hmis-update-banner__btn:hover {
  transform: translateY(-1px);
}

/* ─── LAYOUT ─── */
.layout {
  display: flex;
  height: 100vh;
  overflow: hidden;
  font-family: var(--app-font-family);
}

.dashboard-theme-enterprise .topbar {
  background: linear-gradient(90deg, #334155 0%, #1e293b 55%, #0f172a 100%);
}

.dashboard-theme-clinical .topbar {
  background: linear-gradient(90deg, #334155 0%, #1e293b 55%, #0f172a 100%);
}

.dashboard-theme-luxury .topbar {
  background: linear-gradient(90deg, #334155 0%, #1e293b 55%, #0f172a 100%);
  border-bottom-color: rgba(255, 255, 255, 0.18);
}

.dashboard-theme-luxury .user-name,
.dashboard-theme-luxury .topbar-module-title span {
  color: #e2e8f0 !important;
}

.dashboard-theme-luxury .user-role {
  color: #94a3b8;
}

.dashboard-theme-enterprise .sidebar {
  background: linear-gradient(180deg, #080b10 0%, #06080a 34%, #061a13 66%, #10c400 100%);
}

.dashboard-theme-enterprise .main {
  background: #f8fafc;
}

.dashboard-theme-clinical .main {
  background: #f4f5f6;
}

.dashboard-theme-luxury .sidebar {
  background: linear-gradient(180deg, #080b10 0%, #06080a 34%, #061a13 66%, #10c400 100%);
}

.dashboard-theme-luxury .main {
  background: #0b1220;
}

.dashboard-theme-luxury .module-grid {
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.96) 0%, rgba(2, 6, 23, 0.98) 100%);
}

.dashboard-theme-luxury .card-free,
.dashboard-theme-luxury .card-premium {
  background: rgba(17, 24, 39, 0.88);
  border-color: rgba(239, 68, 68, 0.45);
}

.dashboard-theme-luxury .card-label,
.dashboard-theme-luxury .workflow-stage-title,
.dashboard-theme-luxury .pv-title,
.dashboard-theme-luxury .pv-subtitle {
  color: #e2e8f0;
}

/* ─── SIDEBAR ─── */
.sidebar {
  width: 232px;
  flex-shrink: 0;
  background: linear-gradient(180deg, #080b10 0%, #06080a 34%, #061a13 66%, #10c400 100%);
  display: flex;
  flex-direction: column;
  padding: 0 0 16px 0;
  overflow-y: auto;
  transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  isolation: isolate;
  border-right: 1px solid rgba(255, 255, 255, 0.18);
}

.sidebar::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.04) 0%, rgba(255, 255, 255, 0.01) 100%);
}

.sidebar-collapsed {
  width: 64px;
}

.brand {
  position: relative;
  padding: 24px 16px 16px;
  border-bottom: 1px solid rgba(255,255,255,0.16);
  margin-bottom: 12px;
}

.sidebar-brand-top {
  display: flex;
  align-items: center;
  gap: 10px;
}

.sidebar-collapse-btn {
  width: 30px;
  height: 30px;
  border: 1px solid rgba(255,255,255,0.28);
  background: rgba(255,255,255,0.14);
  color: #fff;
  cursor: pointer;
  font-size: 1.2rem;
  font-weight: 900;
  flex-shrink: 0;
}

.brand-logo-main {
  width: 100%;
  max-width: 172px;
  height: auto;
  display: block;
  object-fit: contain;
}

.brand-title {
  font-size: 1.62rem;
  font-weight: 800;
  color: #ffffff;
  letter-spacing: 0.01em;
  line-height: 1.1;
  font-family: "Nunito", "Baloo 2", sans-serif;
  white-space: nowrap;
  text-shadow: 0 2px 9px rgba(0, 0, 0, 0.45);
}

.brand-sub {
  font-size: 0.8rem;
  color: rgba(255,255,255,0.82);
  letter-spacing: 0.06em;
  font-family: "Baloo 2", "Nunito", sans-serif;
  text-transform: uppercase;
  display: block;
  margin-top: 3px;
  transition: opacity 0.2s;
}

.sidebar-collapsed .brand-title,
.sidebar-collapsed .brand-sub,
.sidebar-collapsed .nav-item span {
  display: none;
}

.sidebar-collapsed .brand-logo-main {
  max-width: 38px;
}

.sidebar-collapsed .brand {
  padding: 20px 0;
  display: flex;
  justify-content: center;
}

.sidebar-collapsed .nav-item {
  justify-content: center;
  padding: 9px 8px;
}

.sidebar-form-section {
  flex: 1;
  padding: 0 10px 10px;
  min-height: 0;
}

.sidebar-section-heading {
  color: rgba(255,255,255,0.95);
  padding: 2px 2px 8px;
}

.sidebar-section-heading span {
  display: block;
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 900;
}

.sidebar-section-heading small {
  display: block;
  margin-top: 3px;
  font-size: 0.78rem;
  color: rgba(255,255,255,0.76);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar-form-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.sidebar-form-btn {
  width: 100%;
  min-height: 36px;
  border: 1px solid rgba(255,255,255,0.16);
  background: rgba(255,255,255,0.1);
  color: #fff;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 8px 10px;
  cursor: pointer;
  text-align: left;
  font-weight: 800;
  font-size: 0.78rem;
}

.sidebar-form-btn:hover {
  background: rgba(255,255,255,0.2);
  transform: translateX(1px);
}

.sidebar-form-btn span {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar-empty-state {
  border: 1px dashed rgba(255,255,255,0.22);
  color: rgba(255,255,255,0.82);
  padding: 12px;
  font-size: 0.78rem;
  display: flex;
  gap: 8px;
  align-items: center;
}

.sidebar-collapsed .sidebar-form-section {
  padding: 0 8px 10px;
}

.sidebar-collapsed .sidebar-form-btn {
  justify-content: center;
  padding: 8px;
}

.sidebar-upgrade-wrap {
  padding: 0 10px 10px;
}

.sidebar-upgrade-btn {
  width: 100%;
  border: 1px solid #b45309;
  border-radius: 11px;
  padding: 10px 12px;
  background: linear-gradient(135deg, #fde68a 0%, #f59e0b 100%);
  color: #78350f;
  font-size: 0.88rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  cursor: pointer;
  box-shadow: 0 8px 16px rgba(217, 119, 6, 0.28);
}

.sidebar-upgrade-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 18px rgba(217, 119, 6, 0.34);
}

.sidebar-upgrade-btn.is-active {
  border-color: #92400e;
  box-shadow: 0 0 0 2px rgba(251, 191, 36, 0.45), 0 12px 18px rgba(217, 119, 6, 0.34);
}

.sidebar-collapsed .sidebar-upgrade-btn span {
  display: none;
}

.sidebar-collapsed .sidebar-upgrade-btn {
  padding: 9px 8px;
}

.nav {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0 10px 8px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border-radius: 11px;
  font-size: 0.96rem;
  font-weight: 700;
  color: rgba(255,255,255,0.92);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: all 0.15s;
  width: 100%;
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.45);
  font-family: "Nunito", sans-serif;
}

.nav-item:hover {
  background: rgba(255,255,255,0.14);
  color: #ffffff;
}

.nav-item svg {
  color: rgba(255, 255, 255, 0.98);
}
.nav-item .hmis-micon {
  color: rgba(255, 255, 255, 0.98);
}

.nav-active {
  background: linear-gradient(135deg, var(--primary, #13d802) 0%, var(--primary, #13d802) 100%) !important;
  color: #ffffff !important;
  box-shadow: 0 6px 16px rgba(17, 197, 138, 0.35);
  border: 1px solid rgba(11, 111, 63, 0.5);
}

.nav-active svg {
  color: #064e3b !important;
}
.nav-active .hmis-micon {
  color: #064e3b !important;
}

.sidebar-hospital-card {
  margin: 8px 12px 0;
  background: linear-gradient(180deg, rgba(20, 184, 111, 0.42) 0%, rgba(9, 121, 79, 0.52) 100%);
  border: 1px solid rgba(110, 231, 183, 0.45);
  border-radius: 14px;
  padding: 14px 12px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.sidebar-hospital-profile {
  flex-direction: column;
  text-align: center;
}

.sidebar-hospital-copy {
  min-width: 0;
}

.sidebar-hospital-copy span {
  display: block;
  font-size: 0.66rem;
  color: rgba(255,255,255,0.72);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 900;
}

.sidebar-hospital-copy strong {
  display: block;
  color: #fff;
  font-size: 0.9rem;
  line-height: 1.2;
  white-space: normal;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.sidebar-hospital-logo {
  width: 82px;
  height: 82px;
  object-fit: contain;
  border-radius: 10px;
  background: var(--hmis-surface);
  border: 1px solid rgba(255,255,255,0.24);
  padding: 4px;
}

.sidebar-hospital-card p {
  font-size: 0.78rem;
  color: rgba(255,255,255,0.95);
  line-height: 1.3;
}

.sidebar-help-wrap {
  padding: 0 10px 10px;
}

.sidebar-help-btn {
  width: 100%;
  border: 1px solid rgba(59, 130, 246, 0.55);
  border-radius: 11px;
  padding: 10px 12px;
  background: linear-gradient(135deg, #1d4ed8 0%, #0ea5e9 100%);
  color: #eff6ff;
  font-size: 0.86rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  cursor: pointer;
  box-shadow: 0 8px 16px rgba(14, 116, 216, 0.24);
}

.sidebar-help-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 10px 20px rgba(14, 116, 216, 0.31);
}

.sidebar-help-btn.is-active {
  border-color: #bfdbfe;
  box-shadow: 0 0 0 2px rgba(191, 219, 254, 0.38), 0 10px 20px rgba(14, 116, 216, 0.31);
}

/* ─── MAIN ─── */
.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: #f4f5f6;
  color: var(--app-text-color);
  font-family: var(--app-font-family);
}

.layout-classic .module-grid {
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 10px;
}

.layout-classic .module-card {
  min-height: 128px;
  border-radius: 14px;
}

.app-mode-dark .main {
  background: #0b1220;
  color: #e2e8f0;
}

.app-mode-dark .module-grid {
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.98) 0%, rgba(2, 6, 23, 0.98) 100%);
}

.app-mode-dark .pv-table-wrap,
.app-mode-dark .workflow-patients,
.app-mode-dark .workflow-form-wrap,
.app-mode-dark .workflow-stage-card,
.app-mode-dark .settings-card {
  background: #111827;
  border-color: #1f2937;
}

.app-mode-dark .pv-table thead {
  background: #0f172a;
}

.app-mode-dark .pv-table td,
.app-mode-dark .pv-table th {
  color: #cbd5e1;
}

.app-mode-dark .settings-card-title,
.app-mode-dark .settings-label,
.app-mode-dark .settings-toggle,
.app-mode-dark .settings-option-title {
  color: #e2e8f0;
}

.app-mode-dark .settings-option-sub,
.app-mode-dark .settings-upload-placeholder {
  color: #94a3b8;
}

.app-mode-dark .settings-option-btn,
.app-mode-dark .settings-mode-btn,
.app-mode-dark .settings-color-input {
  background: #0f172a;
  border-color: #334155;
  color: #e2e8f0;
}

.app-mode-dark .settings-option-btn.is-active,
.app-mode-dark .settings-mode-btn.is-active {
  background: rgba(37, 99, 235, 0.2);
  border-color: #3b82f6;
}

.app-mode-dark .receipt-grid p,
.app-mode-dark .receipt-grid strong {
  color: #e2e8f0;
}

/* ─── TOPBAR ─── */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  background: linear-gradient(90deg, #334155 0%, #1e293b 55%, #0f172a 100%);
  border-bottom: 1px solid rgba(255, 255, 255, 0.18);
  color: #f8fafc;
  flex-shrink: 0;
  position: relative;
  z-index: 40;
}

.topbar-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.topbar-module-title {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #ffffff;
}

.topbar-back-btn {
  border: 1px solid rgba(255, 255, 255, 0.25);
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
  border-radius: 999px;
  padding: 8px 14px;
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}

.topbar-back-btn:hover {
  border-color: rgba(255, 255, 255, 0.42);
  background: rgba(255, 255, 255, 0.22);
  color: #ffffff;
  transform: translateY(-1px);
}

.sidebar-line-toggle {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  background: rgba(255, 255, 255, 0.16);
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  cursor: pointer;
  flex-shrink: 0;
}

.sidebar-line-toggle span {
  display: block;
  width: 14px;
  height: 2px;
  background: #ffffff;
  border-radius: 2px;
}

.sidebar-line-toggle:hover {
  background: rgba(255, 255, 255, 0.26);
  border-color: rgba(255, 255, 255, 0.5);
}

.search-wrap {
  position: relative;
  width: min(320px, 50vw);
  max-width: min(320px, 50vw);
}

.search-input {
  width: 100%;
  padding: 10px 16px 10px 38px;
  background: rgba(15, 23, 42, 0.75);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 999px;
  font-size: 0.9rem;
  outline: none;
  color: #ffffff;
  transition: border 0.2s;
}
.search-input::placeholder {
  color: rgba(255, 255, 255, 0.8);
}
.search-input:focus { border-color: rgba(255, 255, 255, 0.42); background: rgba(15, 23, 42, 0.85); }

.topbar-right { display: flex; align-items: center; gap: 12px; }

.module-search-panel,
.topbar-panel {
  position: absolute;
  z-index: 50;
  background: #fff;
  color: #0f172a;
  border: 1px solid rgba(15, 23, 42, 0.12);
  box-shadow: 0 18px 36px rgba(15, 23, 42, 0.18);
}

.module-search-panel {
  top: calc(100% + 8px);
  left: 0;
  right: auto;
  width: min(420px, 78vw);
  max-height: 360px;
  overflow-y: auto;
  border-radius: 8px;
  padding: 8px;
}

.module-search-result {
  width: 100%;
  border: 0;
  background: transparent;
  color: #0f172a;
  display: flex;
  align-items: center;
  gap: 10px;
  border-radius: 8px;
  padding: 10px;
  cursor: pointer;
  text-align: left;
  transition: background 0.16s ease, transform 0.16s ease;
}

.module-search-result:hover { background: #f1f5f9; transform: translateX(2px); }
.module-search-result span { display: flex; flex-direction: column; min-width: 0; }
.module-search-result strong { font-size: 0.84rem; font-weight: 900; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.module-search-result small,
.module-search-empty { font-size: 0.7rem; color: #64748b; font-weight: 700; }

.topbar-icon-btn {
  width: 38px;
  height: 38px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,0.32);
  background: rgba(255,255,255,0.1);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: relative;
}

.topbar-icon-btn:hover { background: rgba(255,255,255,0.22); border-color: rgba(255,255,255,0.42); transform: translateY(-1px); }
.topbar-icon-btn svg {
  color: #ffffff;
  stroke: #ffffff;
}
.topbar-icon-btn .hmis-micon {
  color: #ffffff;
}
.topbar-popover-wrap { position: relative; }
.topbar-alert-count {
  position: absolute;
  top: -5px;
  right: -5px;
  min-width: 17px;
  height: 17px;
  border-radius: 999px;
  background: #ef4444;
  color: #ffffff;
  font-size: 0.65rem;
  font-weight: 900;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 2px solid #0f172a;
}

.topbar-panel {
  top: calc(100% + 10px);
  right: 0;
  width: min(360px, 86vw);
  padding: 12px;
}

.profile-panel {
  width: min(430px, 90vw);
  padding: 18px;
}

.topbar-panel-header {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: flex-start;
  margin-bottom: 10px;
}

.topbar-panel-header strong { display: block; font-size: 0.86rem; }
.topbar-panel-header span { display: block; font-size: 0.72rem; color: #64748b; }
.topbar-panel-header button {
  border: 0;
  background: #f1f5f9;
  color: #334155;
  width: 24px;
  height: 24px;
  cursor: pointer;
}

.notification-list { display: flex; flex-direction: column; gap: 8px; max-height: 300px; overflow: auto; }
.notification-item {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 9px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}
.notification-item strong,
.notification-item span,
.notification-item small { display: block; font-size: 0.76rem; }
.notification-item span { color: #64748b; }
.notification-item small { color: #0f766e; font-weight: 900; }
.topbar-panel-empty { color: #64748b; font-size: 0.82rem; margin: 0; }

.profile-panel-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}

.profile-panel-avatar {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  background: #0f766e;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
}

.profile-panel-card strong,
.profile-panel-card span { display: block; }
