/* ─── MODULE GRID ─── */
.module-grid {
  flex: 1;
  overflow-y: auto;
  padding: 4px 20px 22px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(182px, 1fr));
  gap: 14px;
  align-content: start;
  position: relative;
  background: linear-gradient(180deg, rgba(255,255,255,0.98) 0%, rgba(247,248,250,0.98) 100%);
  border-top: 1px solid rgba(148, 163, 184, 0.24);
}

.module-grid::before {
  content: "";
  position: absolute;
  width: 420px;
  height: 470px;
  left: 50%;
  top: 52%;
  transform: translate(-50%, -50%);
  border-radius: 44% 44% 48% 48%;
  pointer-events: none;
  opacity: 0.23;
  background:
    linear-gradient(90deg, #000 0%, #000 29%, #fff 29%, #fff 36%, #bb1e2d 36%, #bb1e2d 64%, #fff 64%, #fff 71%, #0b6f3f 71%, #0b6f3f 100%);
  box-shadow: inset 0 0 0 10px rgba(255,255,255,0.24);
  z-index: 0;
}

.module-grid > * {
  position: relative;
  z-index: 1;
}

.module-grid-compact {
  grid-template-columns: repeat(auto-fill, minmax(152px, 1fr));
  gap: 10px;
}

/* ─── CARDS ─── */
.module-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 18px 10px 14px;
  border-radius: 18px;
  cursor: pointer;
  border: none;
  font-family: inherit;
  text-align: center;
  background: #ffffff;
  color: #111827;
  min-height: 144px;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
  overflow: visible;
}

.module-grid-compact .module-card {
  min-height: 122px;
  padding: 18px 10px 14px;
}
.module-card:hover {
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.15);
}

/* Free — white with red outline like reference */
.card-free {
  background: #fafafa;
  box-shadow: 0 6px 14px rgba(0,0,0,0.16);
