}
.card-free .card-icon { color: #9ca3af; }
.card-free .card-label { color: #111827; }

/* Premium — same base with gold accent */
.card-premium {
  background: #fafafa;
  box-shadow: 0 8px 16px rgba(0,0,0,0.16);
  border: 1.4px solid rgba(184, 15, 34, 0.66);
}
