}

.card-icon { display: flex; align-items: center; justify-content: center; }
.card-icon svg {
  filter: drop-shadow(0 3px 3px rgba(0, 0, 0, 0.22));
}

.hmis-micon {
  line-height: 1;
  color: #a1a1aa;
  font-variation-settings:
    "FILL" 0,
    "wght" 450,
    "GRAD" 0,
    "opsz" 24;
}

.module-card::after {
  content: "";
  position: absolute;
  top: -7px;
  right: -7px;
  width: 31px;
  height: 40px;
  border-radius: 15px 15px 16px 16px;
  border: 1px solid rgba(0, 0, 0, 0.25);
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.24);
  background:
    linear-gradient(90deg, #000 0%, #000 30%, #fff 30%, #fff 35%, #bb1e2d 35%, #bb1e2d 65%, #fff 65%, #fff 70%, #0b6f3f 70%, #0b6f3f 100%),
