.pv-del { background: none; border: none; cursor: pointer; padding: 4px 6px; border-radius: 6px; color: #94a3b8; transition: all 0.15s; }
.pv-del:hover { background: #fee2e2; color: #dc2626; }

.pv-table-action {
  position: relative;
  width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 8px;
  color: #ffffff;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.pv-table-action[data-tooltip]::after {
  content: attr(data-tooltip);
  position: absolute;
  left: 50%;
  bottom: calc(100% + 8px);
  transform: translateX(-50%) translateY(4px);
  opacity: 0;
  pointer-events: none;
  white-space: nowrap;
  border-radius: 6px;
  background: #0f172a;
  color: #ffffff;
  padding: 5px 8px;
  font-size: 0.7rem;
  font-weight: 700;
  line-height: 1;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.22);
  transition: opacity 0.14s ease, transform 0.14s ease;
  z-index: 30;
}

.pv-table-action[data-tooltip]::before {
  content: "";
  position: absolute;
  left: 50%;
  bottom: calc(100% + 3px);
  transform: translateX(-50%) translateY(4px);
  opacity: 0;
  pointer-events: none;
  border: 5px solid transparent;
  border-top-color: #0f172a;
  transition: opacity 0.14s ease, transform 0.14s ease;
  z-index: 30;
}

.pv-table-action[data-tooltip]:hover::after,
.pv-table-action[data-tooltip]:hover::before,
.pv-table-action[data-tooltip]:focus-visible::after,
.pv-table-action[data-tooltip]:focus-visible::before {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

.pv-table-action:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 16px rgba(15, 23, 42, 0.16);
}

