}

.subscription-mpesa-hint {
  margin: 0;
  font-size: 0.76rem;
  color: #64748b;
}

.subscription-flow-notice {
  margin: 0;
  font-size: 0.82rem;
  color: #0f766e;
  font-weight: 600;
}

.settings-view {
  flex: 1;
  overflow-y: auto;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.settings-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 14px;
}

.settings-reset-btn {
  white-space: nowrap;
}

.settings-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
