/* Splash + Auth Experience */
.splash-root,
.auth-root {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(70rem 40rem at 5% 10%, rgba(59, 130, 246, 0.22), transparent 60%),
    radial-gradient(60rem 36rem at 95% 95%, rgba(16, 185, 129, 0.2), transparent 60%),
    linear-gradient(140deg, #081025 0%, #0f172a 35%, #13233f 70%, #1f3560 100%);
  position: relative;
  overflow: hidden;
}

.splash-glow {
  position: absolute;
  border-radius: 999px;
  filter: blur(40px);
  opacity: 0.65;
  pointer-events: none;
}

.splash-glow-1 {
  width: 360px;
  height: 360px;
  background: rgba(241, 196, 15, 0.38);
  top: -80px;
  left: -70px;
}

.splash-glow-2 {
  width: 320px;
  height: 320px;
  background: rgba(59, 130, 246, 0.42);
  bottom: -90px;
  right: -60px;
}

.splash-card,
.auth-card {
  width: min(980px, 96vw);
  background: rgba(255, 255, 255, 0.95);
  border: 1px solid rgba(255, 255, 255, 0.7);
  border-radius: 26px;
  box-shadow:
    0 28px 90px rgba(8, 16, 37, 0.38),
    0 2px 0 rgba(255, 255, 255, 0.8) inset;
  backdrop-filter: blur(8px);
}

.splash-card {
  padding: 42px 44px;
  position: relative;
}

.splash-badge {
  display: inline-flex;
  padding: 7px 12px;
  border-radius: 999px;
  background: #eff6ff;
  color: #1d4ed8;
  border: 1px solid #bfdbfe;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.splash-actions,
.auth-actions {
  margin-top: 26px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.splash-btn-primary,
.splash-btn-secondary {
  padding: 11px 18px;
  border-radius: 12px;
  border: 1px solid transparent;
  font-size: 0.9rem;
  font-weight: 700;
  cursor: pointer;
}

.splash-btn-primary {
  background: linear-gradient(135deg, #1d4ed8, #3b82f6);
  color: white;
  box-shadow: 0 10px 24px rgba(37, 99, 235, 0.32);
}

.splash-btn-primary:hover {
  transform: translateY(-1px);
}

.splash-btn-secondary {
  background: #f8fafc;
  border-color: #cbd5e1;
  color: #334155;
}

.auth-card {
  padding: 22px 24px;
  width: min(900px, 96vw);
}

.auth-card h2 {
  font-size: 1.35rem;
  color: #0f172a;
  font-weight: 800;
}

.auth-card p {
  font-size: 0.86rem;
  color: #64748b;
  margin-top: 2px;
  margin-bottom: 10px;
}

.auth-link-row {
  margin-top: 14px;
  font-size: 0.78rem;
  color: #64748b;
}

.auth-link-row a {
  color: #2563eb;
  font-weight: 700;
  text-decoration: none;
}

.auth-link-row a:hover {
  text-decoration: underline;
}

.auth-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.auth-card label {
  display: flex;
  flex-direction: column;
  gap: 5px;
  font-size: 0.76rem;
  font-weight: 700;
  color: #475569;
}

.auth-input {
  border: 1px solid #cbd5e1;
  background: white;
  border-radius: 10px;
  padding: 10px 12px;
  font-size: 0.86rem;
  color: #0f172a;
  outline: none;
}

.auth-input:focus {
  border-color: #60a5fa;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.setup-landing-shell {
  width: min(1120px, 96vw);
  max-height: calc(100vh - 38px);
  overflow-y: auto;
  background: rgba(255,255,255,0.96);
  border: 1px solid rgba(255,255,255,0.72);
  box-shadow: 0 28px 90px rgba(8, 16, 37, 0.38);
  padding: 22px;
}

.setup-landing-header {
  display: grid;
  grid-template-columns: auto 1fr minmax(150px, 220px);
  gap: 18px;
  align-items: center;
}

.setup-eyebrow {
  margin: 0;
  color: #0f766e;
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.setup-landing-header h1,
.setup-congrats h1 {
  margin: 3px 0 4px;
  color: #0f172a;
  font-size: clamp(1.45rem, 3vw, 2.15rem);
