}

.setup-copy {
  margin: 0;
  color: #64748b;
  font-size: 0.9rem;
}

.setup-progress span {
  display: block;
  text-align: right;
  color: #0f766e;
  font-weight: 900;
  margin-bottom: 6px;
}

.setup-progress div {
  height: 8px;
  background: #e2e8f0;
