}

.setup-progress i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #0f766e, #22c55e);
}

.setup-pill-row {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding: 18px 0 12px;
}

.setup-pill {
  border: 1px solid #cbd5e1;
  background: #f8fafc;
  color: #334155;
  padding: 8px 10px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  cursor: pointer;
  font-weight: 800;
  font-size: 0.76rem;
}

.setup-pill.is-active {
  background: #dcfce7;
  border-color: #22c55e;
  color: #166534;
}

.setup-form-card {
  border: 1px solid #e2e8f0;
  background: #fff;
  padding: 16px;
}

.setup-panel-heading {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
}

.setup-panel-icon {
  width: 44px;
  height: 44px;
  background: #ecfdf5;
  color: #0f766e;
  display: flex;
  align-items: center;
  justify-content: center;
}

.setup-panel-heading p,
.setup-panel-heading h2,
.setup-panel-heading span {
