  display: block;
}

.setup-panel-heading p { color: #0f766e; font-size: 0.72rem; font-weight: 900; }
.setup-panel-heading h2 { color: #0f172a; font-size: 1.1rem; }
.setup-panel-heading span { color: #64748b; font-size: 0.82rem; }

.setup-field-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.setup-field-grid label,
.setup-choice-field,
.setup-file-picker {
  display: flex;
  flex-direction: column;
  gap: 6px;
  color: #475569;
  font-weight: 800;
  font-size: 0.76rem;
}

.setup-field-grid input,
.setup-field-grid select,
.setup-field-grid textarea {
  border: 1px solid #cbd5e1;
  background: #fff;
  color: #0f172a;
  padding: 10px 11px;
