}

.setup-field-grid textarea { min-height: 88px; resize: vertical; }

.setup-choice-field {
  border: 1px solid #e2e8f0;
  padding: 10px;
  margin: 0;
}

.setup-choice-field legend { padding: 0 4px; }
.setup-choice-field div { display: flex; flex-wrap: wrap; gap: 8px; }
.setup-choice-field label { flex-direction: row; align-items: center; gap: 5px; font-weight: 700; }

.setup-file-picker input { display: none; }
.setup-file-picker b {
  min-height: 42px;
  border: 1px dashed #94a3b8;
  background: #f8fafc;
