  background: transparent;
  color: #2563eb;
  cursor: pointer;
  font-weight: 900;
}

.setup-actions {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 16px;
}

.setup-congrats {
  text-align: center;
  max-width: 680px;
