/* Animated Intro Splash */
.hmis-splash {
  min-height: 100vh;
  display: grid;
  place-items: center;
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(50rem 30rem at 18% 14%, rgba(22, 163, 74, 0.2), transparent 62%),
    radial-gradient(46rem 28rem at 86% 78%, rgba(37, 99, 235, 0.16), transparent 62%),
    linear-gradient(135deg, #0b1514 0%, #12202b 52%, #101827 100%);
}

.hmis-splash-aurora {
  position: absolute;
  inset: -18%;
  background:
    conic-gradient(from 110deg at 50% 50%, rgba(34, 197, 94, 0.1), rgba(37, 99, 235, 0.11), rgba(20, 184, 166, 0.1), rgba(34, 197, 94, 0.1));
  filter: blur(64px);
  opacity: 0.62;
  animation: splashAurora 12s ease-in-out infinite alternate;
}

.hmis-splash-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(148, 163, 184, 0.11) 1px, transparent 1px),
    linear-gradient(90deg, rgba(148, 163, 184, 0.11) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: linear-gradient(to bottom, transparent 0%, #000 30%, #000 76%, transparent 100%);
  opacity: 0.38;
}

.hmis-splash-overlay {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(3, 7, 18, 0.72), transparent 38%, rgba(3, 7, 18, 0.58)),
    linear-gradient(to bottom, rgba(3, 7, 18, 0.12), rgba(3, 7, 18, 0.72));
}

.hmis-splash-orbit {
  position: absolute;
  border: 1px solid rgba(226, 232, 240, 0.16);
  border-radius: 999px;
  box-shadow: inset 0 0 40px rgba(34, 197, 94, 0.08);
}

.hmis-splash-orbit::after {
  content: "";
  position: absolute;
  top: 50%;
  left: -5px;
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: #22c55e;
  box-shadow: 0 0 16px rgba(34, 197, 94, 0.7);
}

.hmis-splash-orbit.orbit-a {
  width: 440px;
  height: 440px;
  right: -120px;
  top: -110px;
  animation: splashOrbit 22s linear infinite;
}

.hmis-splash-orbit.orbit-b {
  width: 360px;
  height: 360px;
  left: -130px;
  bottom: -120px;
  animation: splashOrbit 28s linear infinite reverse;
}

.hmis-splash-pulse {
  position: absolute;
  width: 420px;
  height: 420px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(34, 197, 94, 0.11), transparent 62%);
  animation: splashPulse 4.2s ease-in-out infinite;
}

.hmis-splash-content {
  position: relative;
  z-index: 2;
  text-align: center;
  padding: 30px 32px 28px;
  border: 1px solid rgba(226, 232, 240, 0.16);
  background:
    linear-gradient(180deg, rgba(15, 23, 42, 0.86), rgba(15, 23, 42, 0.68)),
    radial-gradient(circle at top, rgba(34, 197, 94, 0.16), transparent 42%);
  backdrop-filter: blur(14px);
  color: #ffffff;
  width: min(640px, 88vw);
  box-shadow: 0 28px 84px rgba(0, 0, 0, 0.32);
  animation: splashCardIn 820ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.hmis-splash-logo-shell {
  position: relative;
  width: 98px;
  height: 98px;
  display: grid;
  place-items: center;
  margin: 0 auto 18px;
}

.hmis-splash-logo-ring {
  position: absolute;
  inset: 0;
  border-radius: 22px;
  background: conic-gradient(from 0deg, #22c55e, #2563eb, #dc2626, #22c55e);
  animation: splashLogoSpin 4.5s linear infinite;
}

.hmis-splash-logo-ring::after {
  content: "";
  position: absolute;
  inset: 4px;
  background: #ffffff;
  border-radius: 18px;
}

.hmis-splash-logo {
  position: relative;
  z-index: 1;
  width: 80px;
  height: 80px;
  object-fit: contain;
  padding: 9px;
}

.hmis-splash-kicker {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin: 0 0 10px;
  padding: 7px 12px;
  border: 1px solid rgba(34, 197, 94, 0.32);
  background: rgba(34, 197, 94, 0.1);
  color: #bbf7d0;
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.hmis-splash-brand {
  font-size: clamp(1.45rem, 3vw, 2.35rem);
  line-height: 1.05;
  letter-spacing: 0;
  margin: 0;
  color: #f8fafc;
  font-weight: 900;
  text-shadow: 0 12px 34px rgba(0, 0, 0, 0.28);
}

.hmis-splash-copy {
  max-width: 520px;
  margin: 10px auto 0;
  color: rgba(226, 232, 240, 0.8);
  font-size: 0.84rem;
  line-height: 1.55;
}

.hmis-splash-status-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin: 18px auto 18px;
}

.hmis-splash-status-grid span {
  display: grid;
  gap: 4px;
  padding: 10px 9px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(15, 23, 42, 0.56);
}

.hmis-splash-status-grid b {
  color: #f8fafc;
  font-size: 0.72rem;
  font-weight: 900;
}

.hmis-splash-status-grid small {
  color: #86efac;
  font-size: 0.66rem;
  font-weight: 800;
  text-transform: uppercase;
}

.hmis-splash-progress-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  align-items: center;
  margin: 0 auto;
  width: min(600px, 86vw);
}

.hmis-splash-progress-track {
  height: 10px;
  border: 1px solid rgba(226, 232, 240, 0.18);
  background: rgba(2, 6, 23, 0.68);
  overflow: hidden;
  position: relative;
}

.hmis-splash-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #22c55e 0%, #06b6d4 52%, #2563eb 100%);
  box-shadow: 0 0 18px rgba(34, 197, 94, 0.62);
  transition: width 180ms ease-out;
}

.hmis-splash-progress-value {
  min-width: 48px;
  text-align: right;
  font-size: 1rem;
  font-weight: 900;
  color: #f8fafc;
  line-height: 1;
}

.hmis-splash-sub {
  margin: 12px 0 0;
  color: rgba(187, 247, 208, 0.92);
  font-size: 0.78rem;
  font-weight: 800;
}

@keyframes splashCardIn {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes splashAurora {
  from { transform: rotate(0deg) scale(1); }
  to { transform: rotate(16deg) scale(1.08); }
}

@keyframes splashOrbit {
  to { transform: rotate(360deg); }
}

@keyframes splashPulse {
  0%, 100% { transform: scale(0.9); opacity: 0.32; }
  50% { transform: scale(1.04); opacity: 0.58; }
}

@keyframes splashLogoSpin {
  to { transform: rotate(360deg); }
}

/* Professional Landing */
.splash-root {
  position: relative;
  background:
    radial-gradient(70rem 40rem at 5% 10%, rgba(220, 38, 38, 0.22), transparent 60%),
    radial-gradient(60rem 36rem at 95% 95%, rgba(15, 118, 110, 0.18), transparent 60%),
    linear-gradient(
      to bottom,
      #0f172a 0%,
      #0f172a 42%,
      #bb1e2d 42%,
      #bb1e2d 58%,
      #0b6f3f 58%,
      #0b6f3f 100%
    );
  background-size: 150% 150%;
  animation: landingGradientShift 14s ease-in-out infinite;
}

.auth-root {
  position: relative;
  background:
    radial-gradient(70rem 40rem at 5% 10%, rgba(220, 38, 38, 0.22), transparent 60%),
    radial-gradient(60rem 36rem at 95% 95%, rgba(15, 118, 110, 0.18), transparent 60%),
    linear-gradient(
      to bottom,
      #0f172a 0%,
      #0f172a 42%,
      #bb1e2d 42%,
      #bb1e2d 58%,
      #0b6f3f 58%,
      #0b6f3f 100%
    );
  background-size: 150% 150%;
  animation: landingGradientShift 14s ease-in-out infinite;
}

.auth-root::before,
.auth-root::after {
  content: "";
  position: absolute;
  border-radius: 999px;
  filter: blur(60px);
  pointer-events: none;
}

.auth-root::before {
  width: 360px;
  height: 360px;
  background: rgba(255, 255, 255, 0.17);
  top: -80px;
  left: -90px;
  animation: landingOrbFloatA 12s ease-in-out infinite;
}

.auth-root::after {
  width: 320px;
  height: 320px;
  background: rgba(0, 0, 0, 0.2);
  bottom: -90px;
  right: -90px;
  animation: landingOrbFloatB 15s ease-in-out infinite;
}

.auth-root.landing-theme-enterprise {
  background:
    radial-gradient(70rem 40rem at 5% 10%, rgba(59, 130, 246, 0.16), transparent 60%),
    radial-gradient(60rem 36rem at 95% 95%, rgba(16, 185, 129, 0.14), transparent 60%),
    linear-gradient(140deg, #eef2ff 0%, #f8fafc 35%, #ffffff 70%, #f1f5f9 100%);
  animation: landingGradientShift 14s ease-in-out infinite;
}

.auth-root.landing-theme-clinical {
  background:
    radial-gradient(70rem 40rem at 5% 10%, rgba(220, 38, 38, 0.22), transparent 60%),
    radial-gradient(60rem 36rem at 95% 95%, rgba(15, 118, 110, 0.18), transparent 60%),
    linear-gradient(
      to bottom,
      #0f172a 0%,
      #0f172a 42%,
      #bb1e2d 42%,
      #bb1e2d 58%,
      #0b6f3f 58%,
      #0b6f3f 100%
    );
  animation: landingGradientShift 14s ease-in-out infinite;
}

.auth-root.landing-theme-luxury {
  background:
    radial-gradient(60rem 40rem at 10% 10%, rgba(148, 163, 184, 0.18), transparent 60%),
    radial-gradient(50rem 34rem at 90% 90%, rgba(251, 191, 36, 0.18), transparent 60%),
    linear-gradient(150deg, #020617 0%, #0b1220 40%, #111827 100%);
  animation: landingGradientShift 14s ease-in-out infinite;
}

.splash-root::before,
.splash-root::after {
  content: "";
  position: absolute;
  border-radius: 999px;
  filter: blur(60px);
  pointer-events: none;
}

.splash-root::before {
  width: 360px;
  height: 360px;
  background: rgba(255, 255, 255, 0.17);
  top: -80px;
  left: -90px;
  animation: landingOrbFloatA 12s ease-in-out infinite;
}

.splash-root::after {
  width: 320px;
  height: 320px;
  background: rgba(0, 0, 0, 0.2);
  bottom: -90px;
  right: -90px;
  animation: landingOrbFloatB 15s ease-in-out infinite;
}

.landing-shell {
  width: min(1080px, 94vw);
  /* Slightly shorter shell + top-aligned content reduces "empty" vertical space
     around the logo and CTA on desktop screens. */
  min-height: min(640px, 84vh);
  position: relative; /* anchor the theme picker to the card */
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
  align-items: start;
  padding: 28px;
  border-radius: 28px;
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid rgba(255, 255, 255, 0.72);
  box-shadow:
    0 26px 80px rgba(8, 16, 37, 0.35),
    0 2px 0 rgba(255, 255, 255, 0.75) inset;
  backdrop-filter: blur(8px);
  z-index: 1;
}

.landing-theme-picker {
  position: absolute;
  top: 16px;
  right: 16px;
  z-index: 5;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
  max-width: min(520px, 72%);
  padding: 6px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid rgba(226, 232, 240, 0.9);
  box-shadow: 0 14px 34px rgba(15, 23, 42, 0.12);
  backdrop-filter: blur(10px);
}

.landing-theme-picker button {
  border: 1px solid #cbd5e1;
  background: #f8fafc;
  color: #334155;
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 0.7rem;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
}

.landing-theme-picker button.is-active {
  border-color: #2563eb;
  background: #dbeafe;
  color: #1e3a8a;
}

@media (max-width: 760px) {
  .landing-theme-picker {
    left: 16px;
    right: 16px;
    max-width: unset;
    justify-content: center;
    border-radius: 18px;
  }
}

.landing-copy {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: flex-start;
}

.landing-title {
  margin-top: 10px;
  font-size: clamp(1.9rem, 4vw, 3.2rem);
  line-height: 1.05;
  color: #0f172a;
  font-weight: 850;
}

.landing-title-logo {
