  line-height: 1.65;
  max-width: 500px;
}

.landing-pills {
  margin-top: 4px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.landing-pills span {
  border-radius: 999px;
  border: 1px solid #cbd5e1;
  background: #f8fafc;
  color: #334155;
  font-size: 0.74rem;
  font-weight: 700;
  padding: 6px 10px;
}

.landing-visual {
  position: relative;
  height: min(620px, 72vh);
}

.landing-image-wrap {
  width: 100%;
  height: 100%;
  border-radius: 20px;
  overflow: hidden;
  border: 1px solid #e2e8f0;
  box-shadow: 0 20px 48px rgba(8, 16, 37, 0.2);
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 10px;
}

.landing-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.splash-actions {
  margin-top: 10px;
  justify-content: flex-start;
}

.landing-stat-card {
  position: absolute;
  display: flex;
  flex-direction: column;
  gap: 3px;
  border-radius: 14px;
  background: rgba(15, 23, 42, 0.88);
  color: #e2e8f0;
  padding: 10px 12px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(6px);
  animation: statGlow 2.8s ease-in-out infinite;
}

.landing-stat-card strong {
  font-size: 1rem;
  color: #facc15;
  font-weight: 800;
}

.landing-stat-card span {
  font-size: 0.72rem;
  color: #cbd5e1;
}

.landing-stat-card.stat-a {
  top: 12px;
  left: 12px;
  animation:
    statFloatA 4.8s ease-in-out infinite,
    statGlow 2.8s ease-in-out infinite;
}

.landing-stat-card.stat-b {
  bottom: 12px;
  right: 12px;
  animation:
    statFloatB 5.2s ease-in-out infinite,
    statGlow 3.1s ease-in-out infinite;
}

