@keyframes landingGradientShift {
  0% {
    background-position: 0% 25%;
  }
  50% {
    background-position: 100% 75%;
  }
  100% {
    background-position: 0% 25%;
  }
}

@keyframes landingOrbFloatA {
  0% {
    transform: translate(0, 0) scale(1);
  }
  50% {
    transform: translate(26px, 18px) scale(1.08);
  }
  100% {
    transform: translate(0, 0) scale(1);
  }
}

@keyframes landingOrbFloatB {
  0% {
    transform: translate(0, 0) scale(1);
  }
  50% {
    transform: translate(-24px, -16px) scale(1.06);
  }
  100% {
    transform: translate(0, 0) scale(1);
