.topbar-panel {
  top: calc(100% + 10px);
  right: 0;
  width: min(360px, 86vw);
  border-radius: 8px;
  padding: 12px;
  overflow: visible;
}

.profile-panel {
  width: min(430px, 90vw);
  padding: 18px;
}

.topbar-panel-header {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: flex-start;
  margin-bottom: 10px;
  padding: 0;
  border-bottom: 0;
  background: transparent;
}

.topbar-panel-header strong {
  display: block;
  color: #0f172a;
  font-size: 0.86rem;
  font-weight: 900;
}

.topbar-panel-header span {
  display: block;
  margin-top: 2px;
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 700;
}

.topbar-panel-header button {
  width: 24px;
  height: 24px;
  border: 0;
  border-radius: 0;
  background: #f1f5f9;
  color: #334155;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 0.92rem;
}

.notification-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 300px;
  overflow: auto;
  padding: 0;
}

.notification-item {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
  padding: 9px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 0;
}

.notification-item + .notification-item {
  margin-top: 0;
}

.notification-item strong,
.notification-item span,
.notification-item small {
  display: block;
  font-size: 0.76rem;
}

.notification-item span {
  color: #64748b;
}

.notification-item small {
  padding: 0;
  background: transparent;
  color: #0f766e;
  font-weight: 900;
  text-transform: none;
}

.profile-panel-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}

.profile-panel-avatar {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  background: #0f766e;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
}

.profile-panel-avatar .hmis-micon,
.profile-panel-avatar svg {
  color: #ffffff;
  stroke: #ffffff;
}

.profile-panel-card strong {
  font-size: 0.98rem;
  color: #0f172a;
  font-weight: 900;
}

.profile-panel-card span {
  color: #64748b;
  font-size: 0.84rem;
  margin-top: 3px;
}

.profile-details {
  margin: 0;
  padding: 8px 16px 16px;
  display: grid;
  gap: 0;
}

.profile-details div {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 0;
  border-top: 0;
  border-bottom: 1px solid #e2e8f0;
}

.profile-details div:last-child {
  border-bottom: 0;
}

.profile-details dt {
  color: #64748b;
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: none;
}

.profile-details dd {
  margin: 0;
  color: #0f172a;
  font-size: 0.82rem;
  font-weight: 900;
  text-align: right;
}

/* Hard override for the live Tauri header. */
.topbar form.search-wrap {
  display: block !important;
  position: relative !important;
  width: min(320px, 50vw) !important;
  max-width: min(320px, 50vw) !important;
}

.topbar .search-input {
  height: 38px !important;
  min-height: 38px !important;
  padding: 10px 16px 10px 38px !important;
  border-radius: 999px !important;
  background: rgba(15, 23, 42, 0.75) !important;
  border: 1px solid rgba(255, 255, 255, 0.2) !important;
  color: #ffffff !important;
  caret-color: #ffffff !important;
  font-size: 0.9rem !important;
  font-weight: 600 !important;
}

.topbar .search-placeholder-overlay {
  display: block !important;
  position: absolute !important;
  z-index: 3 !important;
  left: 38px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  color: rgba(255, 255, 255, 0.82) !important;
  font-size: 0.9rem !important;
  font-weight: 600 !important;
  pointer-events: none !important;
}

.topbar form.search-wrap.is-empty::after {
  content: none !important;
  display: none !important;
  position: absolute !important;
  z-index: 10 !important;
  left: 38px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  color: rgba(255, 255, 255, 0.82) !important;
  font-size: 0.9rem !important;
  font-weight: 600 !important;
  line-height: 1 !important;
  pointer-events: none !important;
}

.topbar form.search-wrap.has-value::after {
  content: "" !important;
  display: none !important;
}

.topbar .user-pill {
  min-height: 42px !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 10px !important;
  padding: 6px 14px !important;
  border-radius: 999px !important;
  border: 1px solid rgba(255, 255, 255, 0.2) !important;
  background: rgba(255, 255, 255, 0.14) !important;
  color: #ffffff !important;
}

.topbar .user-pill .avatar {
  width: 34px !important;
  height: 34px !important;
  border-radius: 50% !important;
  background: #0f172a !important;
  color: #ffffff !important;
  font-size: 0.82rem !important;
  font-weight: 800 !important;
}

.topbar .user-pill .user-name {
  color: #ffffff !important;
  font-size: 0.82rem !important;
  font-weight: 600 !important;
}

.topbar .profile-panel {
  width: min(430px, 90vw) !important;
  padding: 0 !important;
  border-radius: 14px !important;
  background: #ffffff !important;
  color: #0f172a !important;
  overflow: hidden !important;
  border: 1px solid rgba(15, 23, 42, 0.12) !important;
  box-shadow: 0 22px 50px rgba(15, 23, 42, 0.24) !important;
}

.profile-hero {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 16px !important;
  padding: 18px !important;
  color: #ffffff !important;
  background:
    radial-gradient(circle at 86% 12%, rgba(34, 197, 94, 0.36), transparent 30%),
    linear-gradient(135deg, #0f172a 0%, #1e3a8a 54%, #0f766e 100%) !important;
}

.profile-hero-main {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 14px;
}

.topbar .profile-panel-avatar {
  width: 56px !important;
  height: 56px !important;
  flex-shrink: 0 !important;
  border-radius: 14px !important;
  background: rgba(255, 255, 255, 0.14) !important;
  color: #ffffff !important;
  border: 1px solid rgba(255, 255, 255, 0.24) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.18) !important;
}

.profile-hero-copy {
  min-width: 0;
}

.profile-kicker {
  display: block;
  margin-bottom: 3px;
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.66rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.profile-hero-copy strong {
  display: block;
  color: #ffffff;
  font-size: 1rem;
  line-height: 1.2;
  font-weight: 900;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profile-hero-copy small {
  display: block;
  margin-top: 3px;
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.8rem;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profile-close-btn {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 8px;
  background: rgba(220, 38, 38, 0.9);
  color: #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  font-weight: 900;
  cursor: pointer;
}

.profile-status-row {
  display: grid;
  grid-template-columns: auto auto 1fr;
  align-items: center;
  gap: 8px;
  margin: 14px 16px 4px;
  padding: 10px 12px;
  border: 1px solid #bbf7d0;
  border-radius: 10px;
  background: #f0fdf4;
}

.profile-status-dot {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: #16a34a;
  box-shadow: 0 0 0 4px rgba(22, 163, 74, 0.14);
}

.profile-status-row strong {
  color: #14532d;
  font-size: 0.78rem;
  font-weight: 900;
}

.profile-status-row small {
  min-width: 0;
  color: #64748b;
  font-size: 0.75rem;
  font-weight: 700;
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

