  position: fixed;
  inset: 0;
  z-index: 70;
  display: flex;
  justify-content: flex-end;
  background: rgba(15, 23, 42, 0.45);
  backdrop-filter: blur(2px);
}

.patient-workspace-slide {
  width: min(560px, calc(100vw - 24px));
  height: 100vh;
  margin: 0;
  border-radius: 0;
  animation: patientSlideIn 180ms ease-out;
  overflow-y: auto;
}

@keyframes patientSlideIn {
  from {
    transform: translateX(100%);
    opacity: 0.7;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

.patient-workspace-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px;
  background: linear-gradient(135deg, #174ea6, #059669);
  color: #ffffff;
}

.patient-workspace-head h3 {
  margin: 0;
  font-size: 1rem;
  font-weight: 850;
}

