.ai-page {
  min-height: calc(100vh - 72px);
  padding: 26px 24px 34px;
  background: #f6f9fc;
  color: #0f172a;
}

.ai-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 18px;
}

.ai-title { display: flex; align-items: flex-start; gap: 12px; min-width: 0; }
.ai-title-mark { width: 42px; height: 42px; flex: 0 0 42px; display: grid; place-items: center; border-left: 4px solid #2563eb; background: #eaf2ff; color: #1d4ed8; }

.ai-header h1 {
  margin: 0 0 7px;
  color: #1e293b;
  font-size: 1.34rem;
  font-weight: 850;
}

.ai-header p {
  max-width: 900px;
  margin: 0;
  color: #607089;
  font-size: 0.84rem;
  font-weight: 550;
  line-height: 1.45;
}

.ai-actions,
.ai-filter {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 10px;
}

.ai-btn {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: 9px;
  padding: 9px 13px;
  color: #ffffff;
  font-size: 0.82rem;
  font-weight: 850;
  cursor: pointer;
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.1);
}

.ai-btn.blue { background: linear-gradient(135deg, #0f172a, #2563eb); }
.ai-btn.green { background: linear-gradient(135deg, #0f172a, #16a34a); }
.ai-btn.ghost {
  border-color: #cbd5e1;
  background: #ffffff;
  color: #334155;
  box-shadow: none;
}

.ai-filter {
  justify-content: flex-start;
  margin-bottom: 16px;
  border: 1px solid #dbe5ee;
  border-radius: 13px;
  padding: 12px 14px;
  background: #ffffff;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05);
}

.ai-filter input,
.ai-filter select {
  min-height: 40px;
  border: 1px solid #d3deeb;
  border-radius: 10px;
  padding: 0 12px;
  background: #ffffff;
  color: #0f172a;
  outline: none;
  font-size: 0.84rem;
  font-weight: 700;
}

.ai-search {
  min-width: min(430px, 100%);
  flex: 1 1 320px;
  min-height: 42px;
  display: flex;
  align-items: center;
  gap: 9px;
  border: 1px solid #d3deeb;
  border-radius: 10px;
  padding: 0 12px;
  color: #64748b;
  background: #ffffff;
}

.ai-search input { width: 100%; border: 0; background: transparent; outline: none; }

.ai-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 14px;
  margin-bottom: 16px;
}

.ai-stat {
  min-height: 78px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid #dbe5ee;
  border-left: 4px solid #2563eb;
  border-radius: 10px;
  padding: 16px;
  background: #ffffff;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.06);
}

.ai-stat span { display: block; margin-bottom: 8px; color: #64748b; font-size: 0.72rem; font-weight: 750; }
.ai-stat strong { display: block; color: #111827; font-size: 1.18rem; font-weight: 900; }
.ai-stat i { width: 34px; height: 34px; display: grid; place-items: center; border-radius: 9px; background: #f8fafc; font-style: normal; }

.ai-pie-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 16px;
}

.ai-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(360px, 0.65fr);
  gap: 18px;
  align-items: start;
}

.ai-main,
.ai-side {
  display: grid;
  gap: 16px;
}

.ai-panel,
.ai-selected {
  border: 1px solid #dbe5ee;
  border-radius: 13px;
  background: #ffffff;
  box-shadow: 0 10px 26px rgba(15, 23, 42, 0.07);
  overflow: hidden;
}

.ai-panel > header {
  border-bottom: 1px solid #e5edf5;
  padding: 14px 16px;
  background: linear-gradient(180deg, #ffffff, #f8fafc);
}

.ai-panel h2 {
  margin: 0;
  color: #111827;
  font-size: 0.98rem;
  font-weight: 850;
}

.ai-table-wrap { position: relative; overflow: auto; }
.ai-table-toolbar { display: flex; align-items: center; justify-content: space-between; min-height: 35px; padding: 7px 10px; border-bottom: 1px solid #e2e8f0; background: #f8fafc; }
.ai-table-toolbar strong { color: #334155; font-size: .72rem; font-weight: 850; }
.ai-table-toolbar button { width: 28px; height: 28px; display: grid; place-items: center; border: 1px solid #cbd5e1; border-radius: 6px; background: #fff; color: #1e40af; cursor: pointer; }
.ai-table-toolbar button:hover { background: #eff6ff; }
.ai-table-wrap.is-expanded { position: fixed; inset: 78px 28px 28px; z-index: 210; overflow: auto; border: 1px solid #cbd5e1; background: #fff; box-shadow: 0 24px 70px rgba(15,23,42,.28); }
.ai-has-expanded-table::after { content: ""; position: fixed; inset: 0; z-index: 200; background: rgba(15,23,42,.34); backdrop-filter: blur(3px); pointer-events: none; }
.ai-table { width: 100%; min-width: 780px; border-collapse: collapse; }
.ai-table th { padding: 12px 14px; background: #f1f5f9; color: #5f7089; text-align: left; font-size: 0.72rem; font-weight: 900; letter-spacing: 0.04em; text-transform: uppercase; }
.ai-table td { border-top: 1px solid #e8eef5; padding: 13px 14px; color: #243247; font-size: 0.82rem; font-weight: 650; vertical-align: middle; }
.ai-table tbody tr { cursor: pointer; }
.ai-table tbody tr:hover { background: #f8fafc; }
.ai-table strong,
.ai-table small { display: block; }
.ai-table strong { color: #111827; font-size: 0.86rem; font-weight: 850; }
.ai-table small { margin-top: 4px; color: #64748b; font-size: 0.72rem; font-weight: 700; }
.ai-empty { height: 76px; color: #64748b !important; text-align: center !important; }
.ai-risk {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 5px 9px;
  background: #e0f2fe;
  color: #075985;
  font-size: 0.7rem;
  font-weight: 900;
  text-transform: uppercase;
}
.ai-risk.high,
.ai-risk.critical { background: #fee2e2; color: #991b1b; }
.ai-risk.medium { background: #fef3c7; color: #92400e; }
.ai-risk.low { background: #dcfce7; color: #166534; }

.ai-pie-layout {
  min-height: 210px;
  display: grid;
  grid-template-columns: 170px minmax(0, 1fr);
  gap: 18px;
  align-items: center;
  padding: 16px;
}

.ai-pie {
  width: 156px;
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  border-radius: 50%;
  box-shadow: inset 0 0 0 22px rgba(255, 255, 255, 0.78), 0 12px 30px rgba(15, 23, 42, 0.12);
}

.ai-pie strong,
.ai-pie span { grid-area: 1 / 1; text-align: center; }
.ai-pie strong { margin-top: -12px; color: #0f172a; font-size: 1.32rem; font-weight: 950; }
.ai-pie span { margin-top: 28px; color: #64748b; font-size: 0.72rem; font-weight: 850; }
.ai-pie-legend { display: grid; gap: 9px; }
.ai-pie-legend button { min-height: 38px; display: flex; align-items: center; gap: 9px; border: 1px solid #dbe5ee; border-radius: 10px; padding: 8px 10px; background: #ffffff; color: #1e293b; text-align: left; font-size: 0.8rem; font-weight: 850; cursor: pointer; }
.ai-pie-legend i { width: 12px; height: 12px; flex: 0 0 auto; border-radius: 999px; }

.ai-selected {
  padding: 16px;
  background: linear-gradient(135deg, #0f172a, #1e3a8a);
  color: #ffffff;
}

.ai-selected span { display: block; color: rgba(255, 255, 255, 0.74); font-size: 0.72rem; font-weight: 900; letter-spacing: 0.04em; text-transform: uppercase; }
.ai-selected h2 { margin: 8px 0 14px; color: #ffffff; font-size: 1.03rem; font-weight: 850; }
.ai-selected dl { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin: 0; }
.ai-selected div { border: 1px solid rgba(255, 255, 255, 0.18); border-radius: 10px; padding: 9px; background: rgba(255, 255, 255, 0.08); }
.ai-selected dt { color: rgba(255, 255, 255, 0.68); font-size: 0.68rem; font-weight: 850; }
.ai-selected dd { margin: 5px 0 0; color: #ffffff; font-size: 0.83rem; font-weight: 900; }
.ai-review-actions { margin-top: 12px; border: 0 !important; padding: 0 !important; background: transparent !important; }
.ai-review-actions > span { display: block; color: rgba(255, 255, 255, 0.72); font-size: 0.68rem; font-weight: 850; text-transform: uppercase; letter-spacing: .06em; }
.ai-review-actions > div { display: flex; gap: 8px; margin-top: 7px; padding: 0; border: 0; background: transparent; }
.ai-review-actions button { display: inline-flex; align-items: center; gap: 5px; border: 1px solid rgba(255,255,255,.35); border-radius: 7px; padding: 7px 10px; color: #fff; background: rgba(255,255,255,.12); font-size: .72rem; font-weight: 800; cursor: pointer; }
.ai-review-actions button:hover:not(:disabled) { background: rgba(255,255,255,.22); }
.ai-review-actions button:disabled { opacity: .5; cursor: not-allowed; }

.ai-factor-list { display: grid; gap: 9px; padding: 12px; }
.ai-factor-list div { border: 1px solid #dbe5ee; border-radius: 10px; padding: 11px 12px; background: #ffffff; }
.ai-factor-list strong,
.ai-factor-list span { display: block; }
.ai-factor-list strong { color: #111827; font-size: 0.82rem; font-weight: 850; }
.ai-factor-list span { margin-top: 4px; color: #64748b; font-size: 0.72rem; font-weight: 700; }
.ai-list { display: grid; gap: 9px; padding: 12px; }
.ai-list button { width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 10px; border: 1px solid #dbe5ee; border-radius: 10px; padding: 11px 12px; background: #ffffff; color: #1e293b; text-align: left; cursor: pointer; }
.ai-list button:hover { border-color: #93c5fd; background: #f8fbff; }
.ai-list strong,
.ai-list small { display: block; }
.ai-list strong { font-size: 0.82rem; font-weight: 850; }
.ai-list small { margin-top: 4px; color: #64748b; font-size: 0.72rem; font-weight: 700; }
.ai-note { margin: 0; padding: 18px 16px; color: #64748b; font-size: 0.82rem; font-weight: 650; }

.ai-modal-backdrop { position: fixed; inset: 0; z-index: 100; display: flex; align-items: center; justify-content: center; padding: 22px; background: rgba(15, 23, 42, 0.5); backdrop-filter: blur(7px); }
.ai-modal { width: min(820px, calc(100vw - 30px)); max-height: calc(100dvh - 34px); display: flex; flex-direction: column; overflow: hidden; border: 1px solid rgba(226, 232, 240, 0.92); border-radius: 16px; background: #ffffff; box-shadow: 0 28px 80px rgba(15, 23, 42, 0.3); }
.ai-modal header { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding: 18px 20px; color: #ffffff; background: linear-gradient(135deg, #0f172a, #1e3a8a, #2563eb); }
.ai-modal header span { color: rgba(255, 255, 255, 0.72); font-size: 0.72rem; font-weight: 900; letter-spacing: 0.04em; text-transform: uppercase; }
.ai-modal h2 { margin: 4px 0 0; color: #ffffff; font-size: 1.12rem; font-weight: 900; }
.ai-modal header button { width: 38px; height: 38px; flex: 0 0 auto; display: grid; place-items: center; border: 1px solid rgba(254, 202, 202, 0.92); border-radius: 10px; background: #dc2626; color: #ffffff; cursor: pointer; }
.ai-form { min-height: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; overflow-y: auto; padding: 18px 20px; }
.ai-form label { display: grid; gap: 7px; border: 1px solid #e2e8f0; border-left: 4px solid #2563eb; border-radius: 10px; padding: 11px; background: #ffffff; color: #334155; font-size: 0.78rem; font-weight: 850; }
.ai-form label.wide { grid-column: 1 / -1; }
.ai-form input,
.ai-form select,
.ai-form textarea { min-height: 40px; width: 100%; border: 1px solid #cbd5e1; border-radius: 8px; padding: 0 11px; background: #ffffff; color: #0f172a; outline: none; font-size: 0.84rem; font-weight: 650; }
.ai-form textarea { min-height: 94px; padding: 10px 11px; resize: vertical; }
.ai-form footer { grid-column: 1 / -1; display: flex; justify-content: flex-end; gap: 10px; border-top: 1px solid #e2e8f0; margin: 4px -20px -18px; padding: 13px 20px; background: #ffffff; }
.ai-form footer button { min-height: 38px; border: 0; border-radius: 9px; padding: 9px 14px; color: #ffffff; font-size: 0.82rem; font-weight: 850; cursor: pointer; }
.ai-form footer button:first-child { background: #64748b; }
.ai-form footer button:last-child { background: #2563eb; }

.ai-toast { position: fixed; right: 22px; top: 84px; z-index: 260; min-width: min(390px, calc(100vw - 34px)); display: grid; grid-template-columns: 34px 1fr 28px; align-items: start; gap: 0 10px; border: 1px solid #dbe5ee; border-left: 4px solid #16a34a; border-radius: 10px; padding: 13px 12px; background: #fff; color: #0f172a; box-shadow: 0 18px 42px rgba(15,23,42,.18); }
.ai-toast.warning { border-left-color: #d97706; }
.ai-toast.error { border-left-color: #dc2626; }
.ai-toast-icon { width: 30px; height: 30px; display: grid; place-items: center; border-radius: 50%; color: #15803d; background: #dcfce7; }
.ai-toast.warning .ai-toast-icon { color: #b45309; background: #fef3c7; }
.ai-toast.error .ai-toast-icon { color: #b91c1c; background: #fee2e2; }
.ai-toast-copy { display: grid; gap: 3px; }
.ai-toast strong { color: #1e293b; font-size: .82rem; font-weight: 900; }
.ai-toast span { color: #64748b; font-size: .77rem; font-weight: 650; line-height: 1.35; }
.ai-toast button { width: 28px; height: 28px; display: grid; place-items: center; border: 1px solid #e2e8f0; border-radius: 6px; background: #f8fafc; color: #475569; cursor: pointer; }
.ai-loading { position: fixed; right: 24px; top: 92px; z-index: 100; border-radius: 999px; padding: 9px 13px; background: #0f172a; color: #ffffff; font-size: 0.76rem; font-weight: 850; box-shadow: 0 14px 30px rgba(15, 23, 42, 0.22); }

@media (max-width: 1180px) {
  .ai-layout { grid-template-columns: 1fr; }
  .ai-pie-grid { grid-template-columns: 1fr; }
}

@media (max-width: 760px) {
  .ai-page { padding: 18px 12px 28px; }
  .ai-header { flex-direction: column; }
  .ai-actions { justify-content: flex-start; }
  .ai-table-wrap.is-expanded { inset: 68px 10px 10px; }
  .ai-toast { right: 10px; top: 68px; min-width: calc(100vw - 20px); }
  .ai-stats,
  .ai-form,
  .ai-selected dl { grid-template-columns: 1fr; }
  .ai-modal { width: 100%; max-height: calc(100dvh - 24px); }
  .ai-pie-layout { grid-template-columns: 1fr; }
  .ai-pie { justify-self: center; }
}

@media (max-width: 1180px) {
  .exec-widget-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .exec-widget.large { grid-column: span 2; }
  .exec-lower { grid-template-columns: 1fr; }
