.pos-btn-info {
  border-color: #2f80ed;
  background: linear-gradient(135deg, #2f80ed, #2563eb);
  color: #ffffff;
  box-shadow: 0 8px 18px rgba(37, 99, 235, 0.22);
}

.pos-print-animation {
  position: fixed;
  z-index: 1400;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(15, 23, 42, 0.58);
  backdrop-filter: blur(3px);
}

.pos-print-scene {
  width: min(330px, calc(100vw - 36px));
  display: grid;
  justify-items: center;
  gap: 8px;
  border: 1px solid #dbeafe;
  border-radius: 12px;
  padding: 28px 24px 24px;
  background: #ffffff;
  box-shadow: 0 24px 70px rgba(15, 23, 42, 0.3);
}

.pos-printer {
  position: relative;
  width: 190px;
  height: 140px;
  margin-bottom: 8px;
}

.pos-printer-top {
  position: absolute;
  top: 10px;
  left: 35px;
  z-index: 2;
  width: 120px;
  height: 70px;
  display: grid;
  place-items: center;
  border-radius: 9px 9px 4px 4px;
  background: linear-gradient(135deg, #164e8b, #0f766e);
  color: #ffffff;
  box-shadow: 0 10px 18px rgba(15, 118, 110, 0.2);
}

.pos-printer-slot {
  position: absolute;
  top: 68px;
  left: 54px;
  z-index: 3;
  width: 82px;
  height: 8px;
  border-radius: 2px;
  background: #0f172a;
}

.pos-printer-body {
  position: absolute;
  bottom: 0;
  left: 20px;
  width: 150px;
  height: 73px;
  border-radius: 9px;
  background: #dbeafe;
  border: 1px solid #93c5fd;
}

.pos-paper {
  position: absolute;
  z-index: 2;
  top: 50px;
  left: 65px;
  width: 60px;
  height: 74px;
  display: grid;
  align-content: start;
  gap: 4px;
  padding: 12px 6px 6px;
  overflow: hidden;
  background: #ffffff;
  color: #334155;
  font-size: 0.52rem;
  text-align: center;
  box-shadow: 0 2px 5px rgba(15, 23, 42, 0.18);
  animation: pos-receipt-feed 1.25s ease-out both;
}

.pos-paper strong { font-size: 0.55rem; color: #0f172a; }
.pos-paper b { color: #047857; }

.pos-print-status {
  color: #0f172a;
  font-size: 0.98rem;
  font-weight: 900;
}

.pos-print-caption {
  color: #64748b;
  font-size: 0.76rem;
  font-weight: 700;
}

@keyframes pos-receipt-feed {
  from { transform: translateY(-34px); opacity: 0; }
  to { transform: translateY(22px); opacity: 1; }
}

.patient-status-badge {
  display: inline-flex;
  align-items: center;
  border: 1px solid #bbf7d0;
  border-radius: 999px;
  padding: 4px 8px;
  background: #f0fdf4;
  color: #166534;
  font-size: 0.68rem;
  font-weight: 900;
  text-transform: uppercase;
}

.patient-status-badge.is-temporary,
.patient-status-badge.is-unknown {
  border-color: #fed7aa;
  background: #fff7ed;
  color: #9a3412;
}

.patient-status-badge.is-inactive,
.patient-status-badge.is-archived,
.patient-status-badge.is-merged {
  border-color: #cbd5e1;
  background: #f8fafc;
  color: #475569;
}

.pos-btn-primary {
  border-color: #047857;
  background: linear-gradient(135deg, #047857, #0f9f6e);
  color: #ffffff;
  box-shadow: 0 8px 18px rgba(4, 120, 87, 0.2);
}

.pos-btn:disabled {
  cursor: not-allowed;
  opacity: 0.5;
  box-shadow: none;
}

.pos-inventory-grid {
  display: grid;
  gap: 10px;
  align-content: start;
  min-height: 390px;
  max-height: 520px;
  overflow: auto;
  padding: 12px;
}

.pos-stock-panel {
  overflow: hidden;
  gap: 0;
  min-height: 500px;
  border: 1px solid #d8e5ef;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
}

.pos-stock-panel .pv-search-bar {
  margin: 0;
  padding: 12px 14px;
  border-bottom: 1px solid #e2e8f0;
  background: #f8fafc;
}

.pos-stock-panel .pv-search-wrap {
  max-width: none;
  min-width: 0;
  flex-basis: 100%;
}

.pos-stock-panel .pv-empty {
  min-height: 300px;
  display: grid;
  place-items: center;
  margin: 0;
}

.pos-stock-card {
  position: relative;
  display: grid;
  gap: 4px;
  border: 1px solid #dbe4ef;
  border-radius: 10px;
  padding: 12px 42px 12px 12px;
  background:
    linear-gradient(135deg, rgba(240, 253, 244, 0.64), rgba(255, 255, 255, 0.96)),
    #ffffff;
  text-align: left;
  cursor: pointer;
  box-shadow: 0 1px 6px rgba(15, 23, 42, 0.04);
}

.pos-stock-card:hover {
  border-color: #86efac;
  box-shadow: 0 12px 22px rgba(22, 163, 74, 0.12);
}

.pos-stock-card strong {
  color: #0f172a;
  font-size: 0.88rem;
  font-weight: 900;
}

.pos-stock-card span,
.pos-stock-card em {
  color: #64748b;
  font-size: 0.78rem;
  font-style: normal;
  font-weight: 760;
}

.pos-stock-card svg {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #16a34a;
}

.pos-cart-panel {
  overflow: hidden;
  min-height: 500px;
  display: flex;
  flex-direction: column;
  border: 1px solid #d8e5ef;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
}

.pos-sale-modal {
  position: fixed;
  z-index: 1200;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 24px;
}

.pos-sale-modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.52);
  backdrop-filter: blur(2px);
}

.pos-sale-modal-card {
  position: relative;
  z-index: 1;
  width: min(880px, 100%);
  max-height: min(900px, calc(100vh - 48px));
  min-height: 0;
  overflow: auto;
  border-radius: 10px;
  box-shadow: 0 24px 70px rgba(15, 23, 42, 0.3);
}

.pos-sale-modal-card .nursing-care-header {
  min-height: 86px;
  align-items: center;
  padding: 18px 22px;
  border-bottom: 1px solid #1e40af;
  background: linear-gradient(135deg, #0f2f68 0%, #164e8b 58%, #126e73 100%);
  color: #ffffff;
  position: sticky;
  top: 0;
  z-index: 2;
}

.pos-sale-modal-card .nursing-care-header > div {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.pos-sale-modal-card .nursing-care-header span:first-child {
  margin: 0;
  color: #bfdbfe;
  font-size: 0.72rem;
  letter-spacing: 0.12em;
}

.pos-sale-modal-card .nursing-care-header strong {
  color: #ffffff;
  font-size: 1.08rem;
  line-height: 1.25;
}

.pos-sale-modal-card .nursing-care-header .pv-badge {
  border: 1px solid rgba(255, 255, 255, 0.32);
  background: rgba(255, 255, 255, 0.14);
  color: #ffffff;
}

.pos-modal-close {
  width: 34px;
  height: 34px;
  display: inline-grid;
  place-items: center;
  margin-left: auto;
  margin-right: 0;
  border: 1px solid #fca5a5;
  border-radius: 6px;
  background: #dc2626;
  color: #ffffff;
  cursor: pointer;
}

.pos-modal-close:hover {
  background: #b91c1c;
}

.pos-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  padding: 14px;
}

.pos-form-intro {
  margin: 0;
  border-bottom: 1px solid #dbe4ef;
  padding: 13px 20px;
  background: #f8fafc;
  color: #475569;
  font-size: 0.82rem;
  font-weight: 700;
}

.pos-form-grid label {
  display: grid;
  gap: 5px;
  min-width: 0;
  align-content: start;
  border: 1px solid #d9e2ec;
  border-left: 4px solid #16a34a;
  border-radius: 7px;
  padding: 12px 13px;
  background: linear-gradient(135deg, #f8fafc, #ffffff);
}

.pos-form-grid label.wide {
  grid-column: 1 / -1;
}

.pos-form-grid span {
  color: #334155;
  font-size: 0.78rem;
  font-weight: 900;
  letter-spacing: 0.01em;
}

.pos-form-grid input,
.pos-form-grid select,
.pos-form-grid textarea {
  width: 100%;
  min-height: 40px;
  border: 1px solid #cbd5e1;
  border-radius: 3px;
  padding: 11px 12px;
  background: #ffffff;
  color: #0f172a;
  font-size: 0.84rem;
  font-weight: 760;
  outline: none;
}

.pos-form-grid label:focus-within {
  border-color: #94a3b8;
  border-left-color: #15803d;
  box-shadow: 0 0 0 2px rgba(22, 163, 74, 0.1);
}

.pos-form-grid input:focus,
.pos-form-grid select:focus,
.pos-form-grid textarea:focus {
  border-color: #0f9f6e;
  box-shadow: 0 0 0 3px rgba(15, 159, 110, 0.12);
}

.pos-cart-list {
  display: grid;
  align-content: start;
  gap: 9px;
  min-height: 145px;
  max-height: 270px;
  overflow: auto;
  padding: 0 14px 14px;
}

.pos-cart-list .pv-empty {
  min-height: 120px;
  display: grid;
  place-items: center;
  margin: 0;
}

.pos-cart-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 76px minmax(120px, 0.5fr) auto;
  align-items: center;
  gap: 8px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  padding: 10px;
  background: #f8fafc;
}

.pos-cart-item strong {
  display: block;
  color: #0f172a;
  font-size: 0.82rem;
  font-weight: 900;
}

.pos-cart-item span {
  color: #64748b;
  font-size: 0.74rem;
  font-weight: 760;
}

.pos-cart-item input {
  min-height: 36px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  padding: 7px 9px;
  font-size: 0.8rem;
}

.pos-cart-item button {
  width: 34px;
  height: 34px;
  display: inline-grid;
  place-items: center;
  border: 1px solid #fecaca;
  border-radius: 8px;
  background: #fef2f2;
  color: #dc2626;
  cursor: pointer;
}

.pos-total-strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-top: 1px solid #e2e8f0;
  padding: 13px 14px;
  background: linear-gradient(135deg, #f8fafc, #ecfdf5);
  color: #334155;
  font-size: 0.9rem;
  font-weight: 850;
}

.pos-total-strip strong {
  color: #0f172a;
  font-size: 1rem;
}

.pos-submit-btn {
  width: auto;
  min-height: 42px;
  margin: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid #0f9f6e;
  border-radius: 9px;
  background: linear-gradient(135deg, #0f9f6e, #16a34a);
  color: #ffffff;
  font-size: 0.84rem;
  font-weight: 900;
  cursor: pointer;
  box-shadow: 0 10px 20px rgba(22, 163, 74, 0.18);
}

.pos-cart-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 0 14px 10px;
}

.pos-secondary-btn,
.pos-suspended-sales summary {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  padding: 7px 10px;
  background: #f8fafc;
  color: #334155;
  font-size: 0.74rem;
  font-weight: 900;
  cursor: pointer;
}

.pos-secondary-btn:hover,
.pos-suspended-sales summary:hover {
  border-color: #0f766e;
  color: #0f766e;
}

.pos-secondary-btn:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.pos-suspended-sales {
  position: relative;
}

.pos-suspended-sales summary {
  list-style: none;
}

.pos-suspended-sales summary::-webkit-details-marker {
  display: none;
}

.pos-suspended-list {
  position: absolute;
  z-index: 3;
  right: 0;
  bottom: calc(100% + 6px);
  display: grid;
  gap: 4px;
  min-width: 270px;
  max-height: 220px;
  overflow: auto;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  padding: 6px;
  background: #ffffff;
  box-shadow: 0 12px 25px rgba(15, 23, 42, 0.14);
}

.pos-suspended-list button {
  border: 0;
  border-radius: 5px;
  padding: 8px;
  background: #f8fafc;
  color: #334155;
  font-size: 0.72rem;
  font-weight: 800;
  text-align: left;
  cursor: pointer;
}

.pos-suspended-list button:hover {
  background: #ecfdf5;
  color: #047857;
}

.pos-submit-btn:hover {
  filter: saturate(1.05);
  box-shadow: 0 14px 26px rgba(22, 163, 74, 0.24);
}

.pos-cart-panel > .pos-submit-btn {
  width: calc(100% - 28px);
  margin: 0 14px 14px;
}

.pos-bottom-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
  gap: 16px;
  align-items: stretch;
}

.pos-bottom-grid > .nursing-clinical-card {
  min-height: 285px;
  border-color: #d8e5ef;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.045);
}

.pos-table-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-right: 14px;
}

.pos-table-heading input {
  width: min(310px, 48%);
  min-height: 36px;
  border: 1px solid #cbd5e1;
  border-radius: 5px;
  padding: 8px 10px;
  color: #0f172a;
  font-size: 0.74rem;
  font-weight: 700;
}

.pos-table-heading input:focus {
  outline: none;
  border-color: #0f766e;
  box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.1);
}

.pos-reconciliation-panel {
  min-height: 500px;
  border-color: #d8e5ef;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
}

.pos-bottom-grid .pv-table-wrap {
  min-height: 0;
  max-width: 100%;
  overflow-x: auto;
}

.pos-receipt-card .pv-empty {
  min-height: 190px;
  display: grid;
  place-items: center;
  margin: 0;
}

.pos-receipt {
  display: grid;
  gap: 12px;
  overflow: hidden;
  border: 1px solid #d8e5ef;
  border-radius: 12px;
  padding: 0;
  background:
    linear-gradient(180deg, #ffffff, #f8fafc),
    #ffffff;
  color: #0f172a;
  font-size: 0.78rem;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.8);
}

.pos-receipt strong,
.pos-receipt b {
  font-weight: 900;
}

.pos-receipt-head {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  padding: 14px;
  background: linear-gradient(135deg, #052e2b, #0f766e);
  color: #ffffff;
}

.pos-receipt-head img {
  width: 48px;
  height: 48px;
  object-fit: contain;
  border-radius: 10px;
  background: #ffffff;
  padding: 5px;
}

.pos-receipt-head strong {
  display: block;
  color: #ffffff;
  font-size: 0.95rem;
  line-height: 1.2;
}

.pos-receipt-head span {
  display: block;
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.7rem;
  font-weight: 760;
  line-height: 1.25;
}

.pos-receipt-meta {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 5px 10px;
  padding: 0 14px;
}

.pos-receipt-meta span {
  color: #64748b;
  font-size: 0.68rem;
  font-weight: 900;
  text-transform: uppercase;
}

.pos-receipt-meta strong {
  color: #0f172a;
  font-size: 0.76rem;
  text-align: right;
}

.pos-receipt-lines {
  display: grid;
  gap: 0;
  margin: 0 14px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  overflow: hidden;
}

.pos-receipt-lines div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 8px;
  align-items: center;
  padding: 9px 10px;
  background: #ffffff;
  border-bottom: 1px solid #e2e8f0;
}

.pos-receipt-lines div:last-child {
  border-bottom: 0;
}

.pos-receipt-lines span {
  display: grid;
  gap: 2px;
  color: #0f172a;
  font-weight: 850;
}

.pos-receipt-lines small {
  color: #64748b;
  font-size: 0.66rem;
  font-weight: 760;
}

.pos-receipt-lines strong {
  color: #334155;
  font-size: 0.72rem;
  white-space: nowrap;
}

.pos-receipt-lines b {
  color: #047857;
  font-size: 0.76rem;
  white-space: nowrap;
}

.pos-receipt-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 0 14px;
  border-radius: 10px;
  padding: 11px 12px;
  background: #ecfdf5;
  color: #065f46;
}

.pos-receipt-total span {
  font-size: 0.76rem;
  font-weight: 900;
  text-transform: uppercase;
}

.pos-receipt-total strong {
  font-size: 1rem;
}

.pos-receipt-footer {
  margin: 0;
  padding: 0 14px 14px;
  color: #64748b;
  font-size: 0.7rem;
  font-weight: 760;
  text-align: center;
}

.pos-discrepancy {
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid #fed7aa;
  border-radius: 10px;
  padding: 10px 12px;
  background: linear-gradient(135deg, #fff7ed, #fffbeb);
  color: #9a3412;
  font-size: 0.82rem;
  font-weight: 850;
}

.pos-reconcile-form {
  padding: 10px 12px 0;
}

.pos-reconcile-form textarea {
  min-height: 76px;
}

.pos-reconcile-submit {
  grid-column: 1 / -1;
  justify-self: start;
  min-width: 170px;
  padding: 0 14px;
}

.pharmacy-pos-view .pv-link-btn {
  min-height: 30px;
  border: 1px solid #bbf7d0;
  border-radius: 8px;
  padding: 5px 10px;
  background: #f0fdf4;
  color: #047857;
  font-size: 0.74rem;
  font-weight: 900;
  cursor: pointer;
}

.pharmacy-pos-view .pv-link-btn:hover {
  background: #dcfce7;
  border-color: #86efac;
}

.pharmacy-pos-view .pv-table {
  min-width: 920px;
}

.pharmacy-pos-view .pv-table td {
  vertical-align: top;
}

.pos-table-subtext {
  display: block;
  margin-top: 3px;
  color: #64748b;
  font-size: 0.68rem;
  font-weight: 700;
}

.pos-drug-list {
  display: block;
  max-width: 230px;
  color: #334155;
  line-height: 1.35;
}

@media print {
  .pos-print-animation {
    display: none !important;
  }
  body * {
    visibility: hidden;
  }

  .pos-receipt-card,
  .pos-receipt-card * {
    visibility: visible;
  }

  .pos-receipt-card {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    border: 0;
    box-shadow: none;
  }
}

@media (max-width: 1100px) {
  .pos-layout,
  .pos-bottom-grid,
  .pos-form-grid {
    grid-template-columns: 1fr;
  }

  .pos-layout {
    align-items: start;
  }

  .pos-cart-item {
    grid-template-columns: 1fr;
  }

  .pos-stock-panel,
  .pos-cart-panel {
    min-height: auto;
  }
}

/* Operating Theatre */
.ot-view {
  background:
    linear-gradient(180deg, rgba(15, 118, 110, 0.04), rgba(248, 250, 252, 0.98) 230px),
    #f8fafc;
}

.ot-header {
  border-left: 4px solid #0f766e;
  padding-left: 14px;
}

.ot-header .pv-title {
  color: #1f2937;
  font-size: 1.28rem;
  font-weight: 900;
}

.ot-btn {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  padding: 8px 12px;
  background: #ffffff;
  color: #334155;
  font-size: 0.8rem;
  font-weight: 850;
  cursor: pointer;
}

.ot-btn.is-primary {
  border-color: #16a34a;
  background: linear-gradient(135deg, #0f9f6e, #16a34a);
  color: #ffffff;
  box-shadow: 0 10px 20px rgba(22, 163, 74, 0.18);
}

.ot-btn.is-danger {
  border-color: #dc2626;
  background: linear-gradient(135deg, #ef4444, #dc2626);
  color: #ffffff;
  box-shadow: 0 10px 20px rgba(220, 38, 38, 0.18);
}

.ot-btn.is-neutral:hover {
