}

.ot-analytics-card,
.ot-timeline {
  display: grid;
  gap: 10px;
}

.ot-analytics-card h3,
.ot-timeline h3 {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0;
  color: #0f172a;
  font-size: 0.88rem;
  font-weight: 900;
}

.ot-util-grid {
  display: grid;
  gap: 8px;
}

.ot-timeline {
  max-height: 260px;
  overflow: auto;
}

.module-form-backdrop {
  position: fixed;
  inset: 0;
  z-index: 110;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(15, 23, 42, 0.46);
}

.ot-modal {
  width: min(880px, calc(100vw - 32px));
  max-height: calc(100vh - 48px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 28px 80px rgba(15, 23, 42, 0.32);
