  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  color: #ffffff;
  cursor: pointer;
}

.ot-modal .module-form-close:hover {
  background: rgba(255, 255, 255, 0.22);
}

.ot-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.ot-form-grid label {
  display: grid;
  gap: 6px;
  color: #334155;
  font-size: 0.76rem;
  font-weight: 900;
}

.ot-form-grid label.wide,
.ot-form-grid .wide,
.ot-submit {
  grid-column: 1 / -1;
}

.ot-check {
  min-height: 42px;
  display: flex !important;
  align-items: center;
  gap: 9px !important;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  padding: 10px 12px;
  background: #f8fafc;
  color: #334155;
  font-size: 0.8rem !important;
  font-weight: 850 !important;
}

.ot-check input {
  width: 16px;
  min-height: 16px;
}

.ot-submit {
  min-height: 44px;
