  font-weight: 900;
  cursor: pointer;
  box-shadow: 0 14px 26px rgba(15, 118, 110, 0.2);
}

.ot-submit:disabled {
  cursor: not-allowed;
  opacity: 0.65;
  box-shadow: none;
}

/* OT workstation controls: darker clinical palette, compact geometry, and clear form hierarchy. */
.ot-view .ot-btn {
