  background: #166534;
  color: #fff;
}

.ot-view .ot-action-grid button:nth-child(2),
.ot-view .ot-action-grid button:nth-child(5),
.ot-view .ot-action-grid button:nth-child(12) {
  border-color: #172554;
  background: #1e3a8a;
  color: #fff;
}

.ot-view .ot-action-grid button:nth-child(6),
.ot-view .ot-action-grid button:nth-child(9) {
  border-color: #991b1b;
  background: #b91c1c;
  color: #fff;
}

.ot-view .ot-action-grid button:nth-child(7),
.ot-view .ot-action-grid button:nth-child(10) {
