/* Consistent, high-contrast notifications for the clinical workflow modules. */
.ot-view .module-notice-toast,
.mortuary-view .module-notice-toast {
  top: 88px;
  right: 24px;
  width: min(480px, calc(100vw - 32px));
  grid-template-columns: 38px minmax(0, 1fr) 30px;
  gap: 12px;
  min-height: 70px;
  padding: 13px 14px 13px 12px;
  border-radius: 5px;
  border-left-width: 5px;
  background: #fff;
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.2);
}

.ot-view .module-notice-toast::before,
.mortuary-view .module-notice-toast::before {
  content: "✓";
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: color-mix(in srgb, var(--notice-color) 14%, #fff);
  color: var(--notice-color);
  font-size: 1.05rem;
  font-weight: 950;
}

.ot-view .module-notice-toast.is-error::before,
.mortuary-view .module-notice-toast.is-error::before,
.ot-view .module-notice-toast.is-warning::before,
.mortuary-view .module-notice-toast.is-warning::before {
  content: "!";
}

.ot-view .module-notice-toast strong,
.mortuary-view .module-notice-toast strong {
  margin-bottom: 4px;
  font-size: 0.7rem;
  letter-spacing: 0.08em;
}

.ot-view .module-notice-toast span,
.mortuary-view .module-notice-toast span {
  color: #334155;
  font-size: 0.84rem;
  font-weight: 750;
}

.ot-view .module-notice-close,
.mortuary-view .module-notice-close {
  position: static;
  width: 30px;
  height: 30px;
  border-radius: 3px;
  background: color-mix(in srgb, var(--notice-color) 10%, #fff);
  color: var(--notice-color);
  font-size: 0.95rem;
}

.ot-view .module-notice-close:hover,
.mortuary-view .module-notice-close:hover {
  background: var(--notice-color);
  color: #fff;
}

.nicu-page.nursing-view .nicu-toast {
  top: 88px;
  right: 24px;
  width: min(480px, calc(100vw - 32px));
  max-width: none;
  min-height: 70px;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) 30px;
  align-items: center;
  gap: 12px;
  padding: 13px 14px 13px 12px;
  border: 1px solid #dbe5f0;
  border-left: 5px solid #16a34a;
  border-radius: 5px;
  color: #0f172a;
  background: #fff;
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.2);
}

.nicu-page.nursing-view .nicu-toast::before {
  content: "✓";
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #dcfce7;
  color: #15803d;
  font-size: 1.05rem;
  font-weight: 950;
}

.nicu-page.nursing-view .nicu-toast.warning { border-left-color: #d97706; }
.nicu-page.nursing-view .nicu-toast.warning::before { content: "!"; background: #ffedd5; color: #b45309; }
.nicu-page.nursing-view .nicu-toast.error { border-left-color: #dc2626; }
.nicu-page.nursing-view .nicu-toast.error::before { content: "!"; background: #fee2e2; color: #b91c1c; }
.nicu-page.nursing-view .nicu-toast strong { color: #0f766e; font-size: 0.7rem; letter-spacing: 0.08em; }
.nicu-page.nursing-view .nicu-toast.warning strong { color: #b45309; }
.nicu-page.nursing-view .nicu-toast.error strong { color: #b91c1c; }
.nicu-page.nursing-view .nicu-toast span { margin-top: 4px; color: #334155; font-size: 0.84rem; font-weight: 750; }
.nicu-page.nursing-view .nicu-toast button { position: static; width: 30px; height: 30px; border-radius: 3px; color: #475569; background: #f1f5f9; cursor: pointer; }
.nicu-page.nursing-view .nicu-toast button:hover { color: #0f172a; background: #e2e8f0; }

@media (max-width: 1180px) {
  .ot-workspace,
  .ot-toolbar,
  .ot-form-grid {
    grid-template-columns: 1fr;
  }

