.icu-table td span {
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 760;
}

.icu-status {
  display: inline-flex !important;
  width: fit-content;
  min-height: 24px;
  align-items: center;
  border-radius: 999px;
  padding: 4px 9px;
  font-size: 0.68rem;
  font-weight: 900;
  text-transform: uppercase;
  white-space: nowrap;
}

.icu-status.active {
  background: #ecfdf5;
  color: #047857;
}

.icu-status.discharged,
.icu-status.transferred {
  background: #eff6ff;
  color: #1d4ed8;
}

.icu-status.deceased {
  background: #fef2f2;
  color: #dc2626;
}

.icu-case-panel {
  display: grid;
  gap: 14px;
  padding: 14px;
}

.icu-case-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid #e2e8f0;
  padding-bottom: 12px;
}

.icu-case-head span {
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.icu-case-head strong {
  display: block;
  color: #0f172a;
  font-size: 1rem;
  font-weight: 900;
}

.icu-case-head p {
  margin: 4px 0 0;
  color: #64748b;
  font-size: 0.78rem;
  font-weight: 760;
}

.icu-action-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}

.icu-action-grid button {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid #d8e5ef;
  border-radius: 2px;
  border-color: #94a3b8;
  background: #e2e8f0;
  color: #1e293b;
  font-size: 0.78rem;
  font-weight: 850;
  cursor: pointer;
}

.icu-action-grid button:hover {
  border-color: #1e3a8a;
  background: #cbd5e1;
  color: #172554;
}

.icu-safety-strip {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.icu-safety-strip div,
.icu-timeline article {
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  padding: 10px;
  background: #f8fafc;
}

.icu-safety-strip span,
.icu-timeline span {
  display: block;
  color: #64748b;
  font-size: 0.68rem;
  font-weight: 900;
  text-transform: uppercase;
}

.icu-safety-strip strong,
.icu-timeline strong {
  display: block;
  margin-top: 3px;
  color: #0f172a;
  font-size: 0.78rem;
  font-weight: 900;
}

.icu-timeline,
.icu-alert-list {
  display: grid;
  gap: 10px;
  max-height: 300px;
  overflow: auto;
}

.icu-timeline h3,
.icu-alert-list h3 {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0;
  color: #0f172a;
  font-size: 0.88rem;
  font-weight: 900;
}

.icu-alert-list article {
  border: 1px solid #fecaca;
  border-left: 4px solid #dc2626;
  border-radius: 10px;
  padding: 10px;
  background: #fef2f2;
}

.icu-alert-list span {
  display: block;
  color: #dc2626;
  font-size: 0.68rem;
  font-weight: 900;
  text-transform: uppercase;
}

.icu-alert-list strong {
  display: block;
  margin-top: 3px;
  color: #7f1d1d;
  font-size: 0.78rem;
  font-weight: 900;
}

.icu-modal {
  width: min(900px, calc(100vw - 32px));
  max-height: calc(100vh - 48px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: 2px;
  background: #ffffff;
  box-shadow: 0 28px 80px rgba(15, 23, 42, 0.32);
  --module-form-accent: #2563eb;
  --module-form-accent-dark: #1d4ed8;
  --module-form-accent-soft: rgba(37, 99, 235, 0.08);
}

.icu-modal .module-form-header {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 72px;
  padding: 15px 18px;
  background: linear-gradient(135deg, #102554 0%, #1d4ed8 58%, #2563eb 100%) !important;
  color: #ffffff;
}

.icu-modal .module-form-title,
.icu-modal .module-form-kicker,
.icu-modal .module-form-icon {
  color: #ffffff;
}

.icu-modal .module-form-close {
  margin-left: auto;
  width: 34px;
  height: 34px;
  display: inline-grid;
  place-items: center;
  border: 1px solid #fecaca;
  border-radius: 2px;
  background: #dc2626;
  color: #ffffff;
  cursor: pointer;
  box-shadow: 0 6px 14px rgba(127, 29, 29, 0.28);
}

.icu-modal .module-form-close:hover {
  background: #b91c1c;
  border-color: #fee2e2;
}

.icu-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.icu-form-grid label {
  display: grid;
  gap: 6px;
  padding: 12px;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #2563eb;
  border-radius: 2px;
  background: rgba(248, 250, 252, 0.72);
  color: #334155;
  font-size: 0.76rem;
  font-weight: 900;
}

.icu-form-grid label.wide,
.icu-form-grid .wide,
.icu-submit {
  grid-column: 1 / -1;
}

.icu-check {
  min-height: 42px;
  display: flex !important;
  align-items: center;
  gap: 9px !important;
  border: 1px solid #e2e8f0;
  border-radius: 2px;
  padding: 10px 12px;
  background: #f8fafc;
  color: #334155;
  font-size: 0.8rem !important;
  font-weight: 850 !important;
}

.icu-check input {
  width: 16px;
  min-height: 16px;
}

.icu-submit {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid #2563eb;
  border-radius: 2px;
  border-color: #1e3a8a;
  background: linear-gradient(135deg, #1e3a8a, #1d4ed8);
  color: #ffffff;
  font-size: 0.86rem;
  font-weight: 900;
  cursor: pointer;
  box-shadow: 0 14px 26px rgba(37, 99, 235, 0.2);
}

.icu-submit:disabled {
  cursor: not-allowed;
  opacity: 0.65;
  box-shadow: none;
}

@media (max-width: 1180px) {
  .icu-workspace,
  .icu-toolbar,
  .icu-form-grid {
    grid-template-columns: 1fr;
  }

  .icu-table-wrap {
    max-height: none;
  }
}

@media (max-width: 720px) {
  .icu-safety-strip,
  .icu-action-grid,
  .icu-stats-grid {
    grid-template-columns: 1fr;
  }
}

