.physiotherapy-view .module-notice-toast {
  position: fixed;
  z-index: 1250;
  top: 78px;
  right: 24px;
  width: min(480px, calc(100vw - 32px));
  min-height: 70px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 14px 14px 14px 16px;
  border: 1px solid color-mix(in srgb, var(--notice-color) 30%, #cbd5e1);
  border-left: 5px solid var(--notice-color);
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 16px 38px rgba(15, 23, 42, 0.2);
  animation: physio-notice-in 180ms ease-out;
}

.physiotherapy-view .module-notice-toast.is-success { --notice-color: #15803d; }
.physiotherapy-view .module-notice-toast.is-warning { --notice-color: #b45309; }

.physio-notice-icon {
  width: 36px;
  height: 36px;
  display: inline-grid;
  place-items: center;
  border-radius: 50%;
  background: color-mix(in srgb, var(--notice-color) 12%, #ffffff);
  color: var(--notice-color);
}

.physiotherapy-view .module-notice-toast > div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.physiotherapy-view .module-notice-toast strong {
  margin: 0;
  color: #164e63;
  font-size: 0.7rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

