.physiotherapy-view .module-notice-close:focus-visible {
  border-color: #dc2626;
  background: #dc2626;
  color: #ffffff;
  outline: none;
}

@keyframes physio-notice-in {
  from { opacity: 0; transform: translate3d(18px, -8px, 0); }
  to { opacity: 1; transform: translate3d(0, 0, 0); }
}

