/* Dental workspace follows the Nutrition module's clean clinical rhythm. */
.dental-view .pv-header { gap: 18px; flex-wrap: wrap; }
.dental-view .pv-header > :first-child { min-width: 0; flex: 1 1 420px; }
.dental-view .nursing-header-actions { max-width: 520px; }
.dental-view .dental-layout {
  grid-template-columns: minmax(300px, .78fr) minmax(0, 1.22fr) !important;
  gap: 16px;
}
.dental-view .nursing-worklist,
.dental-view .nursing-care-panel { min-width: 0; }
.dental-view .dental-filter-bar {
  grid-template-columns: minmax(0, 1fr) 132px 146px;
  gap: 10px;
}
.dental-view .dental-filter-bar > *,
.dental-view .dental-filter-bar .pv-search-wrap,
.dental-view .dental-filter-bar .pv-search { min-width: 0; }
.dental-view .dental-action-row { gap: 8px; padding: 12px 14px; }
.dental-view .dental-action-btn { border-radius: 3px; min-height: 38px; }
.dental-view .dental-action-btn,
.dental-view .dental-action-btn svg,
.dental-view .dental-action-btn.is-warning,
.dental-view .dental-action-btn.is-warning svg {
  color: #ffffff !important;
}
.dental-view .dental-action-btn { flex: 1 1 145px; min-width: 0; }
.dental-view .dental-chart-shell { margin: 14px; border-radius: 4px; }
.dental-view .dental-info-card { border-radius: 4px; }
.dental-view .dental-tooth { border-radius: 4px; }
.dental-view .dental-detail-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  gap: 12px;
}
.dental-view .dental-info-card { min-width: 0; }
.dental-view .dental-info-card h3,
.dental-view .dental-info-card p { overflow-wrap: anywhere; }
.dental-view .dental-plan-table { min-width: 0; overflow-x: auto; }
.dental-view .pv-table tbody tr { cursor: pointer; transition: background 120ms ease, box-shadow 120ms ease; }
.dental-view .pv-table tbody tr:hover { background: #eff6ff; box-shadow: inset 3px 0 0 #2563eb; }
.dental-view .pv-table tbody tr.nursing-selected-row { background: #eff6ff; box-shadow: inset 3px 0 0 #2563eb; }

@media (max-width: 980px) {
  .dental-view .dental-layout { grid-template-columns: 1fr !important; }
  .dental-view .dental-detail-grid { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; }
  .dental-view .nursing-header-actions { max-width: none; }
}

@media (max-width: 680px) {
  .dental-view .dental-filter-bar { grid-template-columns: 1fr; }
  .dental-view .dental-detail-grid { grid-template-columns: 1fr !important; }
}

@media (max-width: 760px) {
  .dental-view .dental-filter-bar { grid-template-columns: 1fr; }
}

/* Infection Control and CSSD module */
.research-view .pv-header {
  align-items: flex-start;
  gap: 18px;
}

.research-view .pv-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.research-view .pv-header-actions .nursing-action-btn {
  min-height: 40px;
  padding: 9px 15px;
  border-radius: 8px;
  font-size: 0.82rem;
  letter-spacing: 0.01em;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.16);
  transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
}

.research-view .pv-header-actions .nursing-action-btn:hover:not(:disabled) {
  transform: translateY(-1px);
  filter: brightness(0.96);
  box-shadow: 0 11px 22px rgba(15, 23, 42, 0.2);
}

.research-view .pv-header-actions .nursing-action-btn.is-muted {
  border-color: #475569;
  background: #334155;
  color: #ffffff;
}

.research-view .pv-header-actions .nursing-action-btn.is-primary {
  border-color: #1d4ed8;
  background: #1d4ed8;
  color: #ffffff;
}

.research-view .pv-header-actions .nursing-action-btn.is-success {
  border-color: #047857;
  background: #047857;
  color: #ffffff;
}

.research-view .pv-header-actions .nursing-action-btn.is-danger {
  border-color: #b91c1c;
  background: #b91c1c;
  color: #ffffff !important;
}

.research-view .pv-header-actions .nursing-action-btn.is-danger svg,
.research-view .research-action-btn.is-danger,
.research-view .research-action-btn.is-warning {
  color: #ffffff !important;
}

.research-view .research-action-btn.is-danger svg,
.research-view .research-action-btn.is-warning svg {
  color: #ffffff !important;
  stroke: currentColor;
}

/* Clinical Research feedback: keep notifications visible but out of the way
   of the worklist, with an explicit status icon and a square dismiss control. */
.research-view .module-notice-toast {
  --notice-color: #15803d;
  top: 86px;
  right: 24px;
  width: min(470px, calc(100vw - 32px));
  min-height: 76px;
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) 30px;
  align-items: center;
  gap: 12px;
  padding: 14px 14px 14px 12px;
  border: 1px solid color-mix(in srgb, var(--notice-color) 28%, #cbd5e1);
  border-left: 5px solid var(--notice-color);
  border-radius: 8px;
  background: #ffffff;
  color: #172033;
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.2), 0 3px 9px rgba(15, 23, 42, 0.08);
  animation: research-notice-in 180ms ease-out;
}

.research-view .module-notice-toast.is-warning { --notice-color: #b45309; }

.research-view .module-notice-toast::before {
  content: "✓";
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--notice-color) 28%, #ffffff);
  border-radius: 6px;
  background: color-mix(in srgb, var(--notice-color) 10%, #ffffff);
  color: var(--notice-color);
  font-size: 1rem;
  font-weight: 900;
}

.research-view .module-notice-toast.is-warning::before { content: "!"; }

.research-view .module-notice-toast > div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.research-view .module-notice-toast strong {
  margin: 0;
  color: var(--notice-color);
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.research-view .module-notice-toast span {
  color: #334155;
  font-size: 0.84rem;
  font-weight: 700;
  line-height: 1.42;
}

.research-view .module-notice-close {
  position: static;
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  background: #f8fafc;
  color: #475569;
  font-size: 1.1rem;
  line-height: 1;
}

.research-view .module-notice-close:hover {
  border-color: var(--notice-color);
  background: var(--notice-color);
  color: #ffffff;
}

@keyframes research-notice-in {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

.research-stat-card {
  position: relative;
  width: 100%;
  overflow: hidden;
  text-align: left;
  cursor: pointer;
}

.research-stat-card:hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 26px rgba(15, 23, 42, 0.11);
}

.research-stat-icon {
  position: absolute;
  right: 14px;
  top: 50%;
  transform: translateY(-50%);
}

.research-layout {
  display: grid;
  grid-template-columns: minmax(360px, 0.88fr) minmax(0, 1.6fr);
  gap: 24px;
  align-items: start;
}

.research-filter-bar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 160px;
  gap: 10px;
  padding: 12px 14px;
}

.research-view .nursing-worklist,
.research-view .nursing-care-panel {
  min-width: 0;
}

.research-action-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding: 14px;
  border-bottom: 1px solid #e2e8f0;
  background: #f8fafc;
}

.research-action-btn {
  min-height: 37px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 8px 11px;
  color: #ffffff;
  font-size: 0.78rem;
  font-weight: 800;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.12);
}

.research-action-btn.is-success,
.research-submit.is-green {
  background: linear-gradient(135deg, #16a34a, #047857);
}

.research-action-btn.is-danger,
.research-submit.is-red {
  background: linear-gradient(135deg, #ef4444, #991b1b);
}

.research-action-btn.is-blue,
.research-submit.is-blue {
  background: linear-gradient(135deg, #2563eb, #0f172a);
}

.research-action-btn.is-purple,
.research-submit.is-purple {
  background: linear-gradient(135deg, #7c3aed, #312e81);
}

.research-action-btn.is-warning,
.research-submit.is-orange {
  background: linear-gradient(135deg, #f59e0b, #7c2d12);
}

.research-protocol-card {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  padding: 14px;
  border-bottom: 1px solid #e2e8f0;
  background: linear-gradient(135deg, #f8fafc, #eef6ff);
}

.research-protocol-card div,
.research-info-card {
  border: 1px solid #dbe7f4;
  border-radius: 8px;
  background: #ffffff;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.06);
}

.research-protocol-card div {
  padding: 12px;
}

.research-protocol-card span,
.research-info-card span {
  display: block;
  color: #64748b;
  font-size: 0.69rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.research-protocol-card strong,
.research-info-card strong {
  display: block;
  margin-top: 5px;
  color: #0f172a;
  font-size: 0.9rem;
}

.research-info-card {
  min-height: 148px;
  padding: 16px;
}

.research-info-card h3 {
  margin: 0 0 12px;
  color: #0f172a;
  font-size: 0.94rem;
}

.research-info-card div + div {
  margin-top: 12px;
}

/* Keep the selected-protocol summary cards compact and readable on desktop;
   the dental module's narrow-screen rule should not collapse this workspace. */
.research-view .dental-detail-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  padding: 0 14px 18px;
}

.research-subgrid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px;
  padding: 0 14px 14px;
}

.research-data-panel {
  min-width: 0;
  width: 100%;
  min-height: 270px;
  border: 1px solid #dbe7f4;
  border-radius: 8px;
  background: #ffffff;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.07);
  overflow: hidden;
}

.research-data-panel h3 {
  margin: 0;
  padding: 13px 14px;
  border-bottom: 1px solid #e2e8f0;
  color: #0f172a;
  font-size: 0.95rem;
}

.research-data-panel .pv-table-wrap {
  border: 0;
  border-radius: 0;
  box-shadow: none;
  min-height: 214px;
  overflow-x: auto;
}

.research-data-panel .pv-table {
  min-height: 214px;
}

.research-data-panel .pv-table .pv-empty {
  height: 160px;
  vertical-align: middle;
}

.research-table-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.research-modal {
  width: min(920px, calc(100vw - 28px));
  max-height: calc(100dvh - 32px);
  overflow: hidden;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  box-shadow: 0 24px 70px rgba(15, 23, 42, 0.28);
}

.research-modal-header {
  min-height: 76px;
  padding: 16px 20px;
  color: #ffffff;
}

.research-modal-heading {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
}

.research-modal-heading > svg {
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  padding: 9px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.12);
}

.research-modal-kicker {
  display: block;
  margin-bottom: 4px;
  color: rgba(255, 255, 255, 0.72);
  font-size: 0.64rem;
  font-weight: 900;
  letter-spacing: 0.14em;
  line-height: 1;
  text-transform: uppercase;
}

.research-protocol-modal {
  width: min(980px, calc(100vw - 28px));
}

.research-protocol-modal .research-modal-header {
  min-height: 86px;
  padding: 19px 24px;
  background: linear-gradient(135deg, #123b57 0%, #16466a 56%, #102f4a 100%);
}

.research-protocol-modal .research-modal-body {
  padding: 0;
  background: #ffffff;
}

.research-protocol-modal .research-form {
  gap: 0;
}

.research-form-intro {
  display: grid;
  gap: 5px;
  padding: 14px 24px;
  border-bottom: 1px solid #dbe4ee;
  background: #f8fafc;
  color: #475569;
  font-size: 0.84rem;
  line-height: 1.45;
}

.research-form-intro strong {
  color: #16466a;
  font-size: 0.9rem;
}

.research-form-intro span {
  font-weight: 600;
}

.research-protocol-modal .research-form > .research-form-grid,
.research-protocol-modal .research-form > .research-field,
.research-protocol-modal .research-form > .research-submit {
  margin-inline: 24px;
}

.research-protocol-modal .research-form > .research-form-grid:first-of-type {
  padding-top: 22px;
}

.research-protocol-modal .research-form > .research-form-grid {
  padding-bottom: 16px;
  gap: 16px;
}

.research-protocol-modal .research-field {
  padding: 13px;
  border: 1px solid #dbe4ee;
  border-left: 4px solid #16a34a;
  border-radius: 4px;
  background: #f8fafc;
}

.research-protocol-modal .research-field:focus-within {
  border-color: #16466a;
  border-left-color: #16a34a;
  background: #ffffff;
  box-shadow: 0 8px 20px rgba(15, 68, 106, 0.1);
}

.research-protocol-modal .research-field input,
.research-protocol-modal .research-field select,
.research-protocol-modal .research-field textarea {
  border-radius: 3px;
  border-color: #cbd5e1;
}

.research-protocol-modal .research-form > .research-field {
  margin-bottom: 16px;
}

.research-protocol-modal .research-submit {
  margin-top: 4px;
  margin-bottom: 24px;
}

.research-modal.is-blue .research-modal-header {
  background: linear-gradient(135deg, #2563eb, #0f172a);
}

.research-modal.is-green .research-modal-header {
  background: linear-gradient(135deg, #16a34a, #052e16);
}

.research-modal.is-red .research-modal-header {
  background: linear-gradient(135deg, #ef4444, #450a0a);
}

.research-modal.is-purple .research-modal-header {
  background: linear-gradient(135deg, #7c3aed, #1e1b4b);
}

.research-modal.is-orange .research-modal-header {
  background: linear-gradient(135deg, #f59e0b, #431407);
}

.research-protocol-modal.research-modal.is-blue .research-modal-header {
  background: linear-gradient(135deg, #123b57 0%, #16466a 56%, #102f4a 100%);
}

.research-modal-header h2 {
  color: #ffffff;
  margin: 0;
  font-family: var(--font-sans, Inter, ui-sans-serif, system-ui, sans-serif);
  font-size: 1.12rem;
  font-weight: 900;
  letter-spacing: -0.015em;
  line-height: 1.2;
}

.research-modal-close {
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid #fee2e2;
  border-radius: 0 !important;
  background: #dc2626;
  color: #ffffff;
  box-shadow: 0 9px 20px rgba(127, 29, 29, 0.4);
  font-size: 1rem;
  transition: transform 160ms ease, background 160ms ease, box-shadow 160ms ease;
}

.research-modal-close:hover {
  background: #b91c1c;
  transform: translateY(-1px);
  box-shadow: 0 11px 22px rgba(127, 29, 29, 0.42);
}

.research-modal-close svg {
  width: 16px;
  height: 16px;
  display: block;
  color: #ffffff;
  stroke-width: 2.7;
}

.research-modal-body {
  max-height: calc(100dvh - 112px);
  overflow-y: auto;
  padding: 22px;
  background: #f8fafc;
}

.research-form {
  display: grid;
  gap: 18px;
}

.research-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.research-field {
  display: grid;
  gap: 7px;
  color: #334155;
  font-size: 0.78rem;
  font-weight: 800;
}

.research-field input,
.research-field select,
.research-field textarea {
  width: 100%;
  min-height: 42px;
  border: 1px solid #cbd5e1;
  border-radius: 5px;
  background: #ffffff;
  padding: 10px 12px;
  color: #0f172a;
  font-size: 0.86rem;
  font-weight: 650;
  outline: none;
}

.research-field input:focus,
.research-field select:focus,
.research-field textarea:focus {
  border-color: #2563eb;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.14);
}

.research-field textarea {
  min-height: 94px;
  resize: vertical;
}

.research-code-area {
  min-height: 180px !important;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: 0.78rem !important;
}

.research-check-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.research-check {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 42px;
  border: 1px solid #dbe7f4;
  border-radius: 8px;
  background: #ffffff;
  padding: 10px 12px;
  color: #334155;
  font-size: 0.82rem;
  font-weight: 800;
}

.research-check input {
  width: 16px;
  height: 16px;
  accent-color: #16a34a;
}

.research-submit {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 0;
  border-radius: 9px;
  padding: 11px 16px;
  color: #ffffff;
  font-size: 0.86rem;
  font-weight: 900;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.16);
  align-self: flex-start;
  min-width: 170px;
}

.research-submit:disabled,
.research-action-btn:disabled {
  cursor: not-allowed;
  opacity: 0.65;
}

@media (max-width: 900px) {
  .research-layout,
  .research-subgrid,
  .research-protocol-card {
    grid-template-columns: 1fr;
  }

  .research-view .dental-detail-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .research-filter-bar,
  .research-form-grid,
  .research-check-grid {
    grid-template-columns: 1fr;
  }

  .research-modal {
    width: 100%;
    max-height: calc(100dvh - 24px);
  }

  .research-view .dental-detail-grid {
    grid-template-columns: 1fr;
  }
}

