  gap: 18px;
}
.cdss-page > .cdss-header { grid-column: 1 / -1; }
.cdss-page > .cdss-sidebar { grid-column: 1; grid-row: 2 / span 3; }
.cdss-page > .cdss-filter,
.cdss-page > .cdss-stats,
.cdss-page > .cdss-layout { grid-column: 2; }
.cdss-sidebar {
  align-self: start;
