  background: #1e3a8a;
  color: #ffffff;
}
.cdss-sidebar-btn.is-clinical {
  border-color: #0f766e;
  background: #0f766e;
  color: #ffffff;
}
.cdss-sidebar-btn.is-clinical:hover { border-color: #115e59; background: #115e59; }
.cdss-sidebar-btn:disabled { cursor: not-allowed; opacity: 0.55; }

.cdss-workflow-backdrop {
  position: fixed;
  inset: 0;
  z-index: 600;
  display: grid;
  place-items: center;
  padding: 18px;
  background: rgba(7, 22, 52, 0.56);
}
.cdss-workflow-modal {
