.cdss-workflow-modal > header button { width: 32px; height: 32px; display: grid; place-items: center; border: 1px solid #fecaca; border-radius: 3px; background: #dc2626; color: #fff; cursor: pointer; }
.cdss-workflow-body { min-height: 0; overflow-y: auto; padding: 16px; }
.cdss-workflow-list { display: grid; gap: 8px; }
.cdss-workflow-list > button,
