/* Keep the main CDSS work sections balanced instead of allowing a long check
   result or wide table to determine the page dimensions. */
.cdss-main > .cdss-panel {
  width: 100%;
  min-width: 0;
}
.cdss-main > .cdss-panel:nth-of-type(2) .cdss-check-grid {
