  padding: 26px 24px 34px;
  background: #f6f9fc;
  color: #0f172a;
}

.ict-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 18px;
}

.ict-header span {
  display: inline-flex;
  margin-bottom: 6px;
  color: #2563eb;
  font-size: 0.76rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.ict-header h1 {
  margin: 0 0 8px;
  color: #1e293b;
  font-size: 1.24rem;
  font-weight: 850;
}

.ict-header p {
  max-width: 860px;
  margin: 0;
  color: #607089;
  font-size: 0.84rem;
  font-weight: 500;
  line-height: 1.45;
}

.ict-header button,
.ict-tabs button,
.ict-card-form button {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: 9px;
  padding: 9px 13px;
  background: linear-gradient(135deg, #0f172a, #2563eb);
  color: #ffffff;
  font-size: 0.82rem;
  font-weight: 850;
  cursor: pointer;
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.1);
}

.ict-header button:disabled,
.ict-card-form button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.ict-toast {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 120;
  min-width: min(380px, calc(100vw - 34px));
  border-radius: 13px;
  padding: 14px 16px;
  color: #ffffff;
  font-weight: 850;
  box-shadow: 0 22px 54px rgba(15, 23, 42, 0.28);
}

.ict-toast.success {
  background: linear-gradient(135deg, #065f46, #16a34a);
}

.ict-toast.warning {
  background: linear-gradient(135deg, #7f1d1d, #dc2626);
}

.ict-stats {
  display: grid;
