  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid #dbe5ee;
  border-left: 4px solid #2563eb;
  border-radius: 10px;
  padding: 14px 16px;
  background: #ffffff;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.06);
}

.ict-stats span {
  display: block;
  margin-bottom: 8px;
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 700;
}

.ict-stats strong {
  color: #111827;
  font-size: 1.24rem;
  font-weight: 900;
}

.ict-stats svg {
  width: 34px;
  height: 34px;
  padding: 7px;
  border-radius: 9px;
  background: #f8fafc;
}

.ict-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  border: 1px solid #dbe5ee;
  border-radius: 13px;
  margin-bottom: 16px;
  padding: 12px 14px;
  background: #ffffff;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05);
}

.ict-tabs button {
  border-color: #cbd5e1;
  background: #ffffff;
  color: #334155;
  box-shadow: none;
}

.ict-tabs button.active {
  border-color: transparent;
  background: linear-gradient(135deg, #0f172a, #2563eb);
  color: #ffffff;
}

.ict-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(360px, 0.75fr);
  gap: 18px;
  align-items: start;
}

.ict-panel,
.ict-card-form {
  border: 1px solid #dbe5ee;
  border-radius: 13px;
  background: #ffffff;
  box-shadow: 0 10px 26px rgba(15, 23, 42, 0.07);
  overflow: hidden;
}

.ict-title {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  border-bottom: 1px solid #e5edf5;
  padding: 14px 16px;
  background: linear-gradient(180deg, #ffffff, #f8fafc);
}

.ict-title svg {
  color: #2563eb;
}

.ict-title h2,
.ict-card-form h2 {
  margin: 0;
  color: #111827;
  font-size: 0.98rem;
  font-weight: 850;
}

.ict-title p {
  margin: 6px 0 0;
  color: #64748b;
  font-size: 0.8rem;
  font-weight: 650;
}

.ict-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
  gap: 10px;
  padding: 12px;
}

.ict-list article {
  min-height: 124px;
  display: grid;
  gap: 8px;
  border: 1px solid #dbe5ee;
  border-left: 4px solid #2563eb;
  border-radius: 10px;
  padding: 12px;
  background: #ffffff;
}

.ict-list article.danger {
  border-left-color: #dc2626;
  background: #fff7f7;
}

.ict-list article span {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.ict-list strong {
  color: #111827;
  font-size: 0.86rem;
  font-weight: 900;
}

.ict-list em {
  flex: 0 0 auto;
  border-radius: 999px;
  padding: 5px 8px;
  background: #e0f2fe;
  color: #075985;
  font-size: 0.68rem;
  font-style: normal;
  font-weight: 900;
}

.ict-list article.danger em {
  background: #fee2e2;
  color: #991b1b;
}

.ict-list small {
  color: #64748b;
  font-size: 0.76rem;
  font-weight: 700;
  line-height: 1.45;
}

.ict-empty {
  grid-column: 1 / -1;
  min-height: 130px;
  display: grid;
  place-items: center;
  border: 1px dashed #c7d4e3;
  border-radius: 10px;
  color: #64748b;
  font-weight: 850;
}

.ict-side {
  display: grid;
  gap: 14px;
}

.ict-card-form {
  display: grid;
  gap: 10px;
  padding: 14px;
}

.ict-card-form h2 {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 10px;
  border-bottom: 1px solid #e5edf5;
}

.ict-card-form label {
  display: grid;
  gap: 7px;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #2563eb;
  border-radius: 10px;
  padding: 10px;
  background: #ffffff;
  color: #334155;
  font-size: 0.76rem;
  font-weight: 850;
}

.ict-card-form input,
.ict-card-form select,
.ict-card-form textarea {
  width: 100%;
  min-height: 38px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  padding: 0 10px;
  background: #ffffff;
  color: #0f172a;
  font-size: 0.82rem;
  font-weight: 650;
  outline: none;
}

.ict-card-form textarea {
  min-height: 72px;
  resize: vertical;
  padding: 9px 10px;
  line-height: 1.4;
}

.ict-form-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

@media (max-width: 1180px) {
  .ict-stats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
