.documents-btn.blue {
  background: linear-gradient(135deg, #0f172a, #2563eb);
  color: #ffffff;
}

.documents-btn.ghost {
  border-color: #cbd5e1;
  background: #ffffff;
  color: #334155;
  box-shadow: none;
}

.documents-table button,
.documents-version-tool button {
  background: linear-gradient(135deg, #0f172a, #16a34a);
  color: #ffffff;
}
.documents-row-actions { display: flex; flex-wrap: wrap; gap: 6px; }
.documents-row-actions button { min-height: 32px; padding: 7px 9px; font-size: .72rem; }
.documents-row-actions button:nth-child(2) { background: linear-gradient(135deg, #0f172a, #2563eb); }

.documents-review-list button {
  background: linear-gradient(135deg, #0f172a, #2563eb);
  color: #ffffff;
}

.documents-review-list div button:nth-child(2) {
  background: linear-gradient(135deg, #0f172a, #16a34a);
  color: #ffffff;
}

.documents-btn:disabled,
.documents-table button:disabled,
.documents-review-list button:disabled,
.documents-version-tool button:disabled,
.documents-modal-form button:disabled {
  opacity: 0.58;
  cursor: not-allowed;
}

.documents-toast {
  border-radius: 10px;
  padding: 11px 13px;
  font-size: 0.82rem;
  font-weight: 850;
}

.documents-toast.success {
  border: 1px solid #bbf7d0;
  background: #ecfdf5;
  color: #166534;
}

.documents-toast.warning {
  border: 1px solid #fed7aa;
  background: #fff7ed;
  color: #9a3412;
}

/* Keep repository notifications compact, neutral, and visible at the top. */
.documents-page > .documents-toast {
  position: fixed;
  top: 18px;
  left: 50%;
  z-index: 2600;
  width: min(520px, calc(100vw - 32px));
  display: flex;
  align-items: center;
  gap: 10px;
  transform: translateX(-50%);
  border: 1px solid #dbe5ee;
  border-left: 4px solid #16a34a;
  border-radius: 0;
  padding: 12px 14px;
  background: #ffffff;
  color: #1e293b;
  box-shadow: 0 16px 38px rgba(15, 23, 42, .2);
}
.documents-page > .documents-toast.warning { border-left-color: #dc2626; color: #334155; }
.documents-toast-icon { display: inline-flex; flex: 0 0 auto; color: #16a34a; }
.documents-toast.warning .documents-toast-icon { color: #dc2626; }
.documents-toast > span:nth-child(2) { flex: 1; font-size: .8rem; line-height: 1.35; }
.documents-toast > button { display: inline-flex; align-items: center; justify-content: center; border: 0; background: transparent; color: #64748b; cursor: pointer; }
.documents-toast > button:hover { color: #0f172a; }

.documents-stats {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 14px;
}

.documents-stats article {
  min-height: 78px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid #dbe5ee;
  border-left: 4px solid #16a34a;
  border-radius: 10px;
  padding: 14px 16px;
  background: #ffffff;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.06);
}

.documents-stats article:nth-child(2) { border-left-color: #2563eb; }
.documents-stats article:nth-child(3) { border-left-color: #d97706; }
.documents-stats article:nth-child(4) { border-left-color: #0f766e; }
.documents-stats article:nth-child(5) { border-left-color: #7c3aed; }
.documents-stats article:nth-child(6) { border-left-color: #dc2626; }

.documents-stats span {
  display: block;
  margin-bottom: 8px;
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 700;
}

.documents-stats strong {
  display: block;
  color: #0f172a;
  font-size: 1.24rem;
  font-weight: 900;
}

.documents-stats article svg {
  width: 34px;
  height: 34px;
  padding: 7px;
  border-radius: 9px;
  background: #f8fafc;
  color: #16a34a;
}

.documents-stats article:nth-child(2) svg { color: #2563eb; }
.documents-stats article:nth-child(3) svg { color: #d97706; }
.documents-stats article:nth-child(4) svg { color: #0f766e; }
.documents-stats article:nth-child(5) svg { color: #7c3aed; }
.documents-stats article:nth-child(6) svg { color: #dc2626; }

.documents-toolbar {
  justify-content: flex-start;
  border: 1px solid #dbe5ee;
  border-radius: 13px;
  padding: 12px 14px;
  background: #ffffff;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05);
}

.documents-toolbar label {
  min-width: min(430px, 100%);
  flex: 1 1 320px;
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1px solid #d3deeb;
  border-radius: 10px;
  padding: 0 12px;
  background: #ffffff;
  color: #64748b;
}

.documents-toolbar input,
.documents-toolbar select {
  width: 100%;
  min-height: 42px;
  border: 0;
  background: transparent;
  color: #0f172a;
  font-size: 0.86rem;
  font-weight: 600;
  outline: none;
}

.documents-toolbar select {
  min-width: 180px;
  flex: 0 0 230px;
  border: 1px solid #d3deeb;
  border-radius: 10px;
  padding: 0 12px;
  background: #ffffff;
}
.documents-toolbar .documents-toolbar-report {
  background: linear-gradient(135deg, #0f172a, #7c3aed);
  color: #fff;
}

.documents-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(360px, 0.75fr);
  gap: 18px;
  align-items: start;
}

.documents-panel {
  border: 1px solid #dbe5ee;
  border-radius: 13px;
  background: #ffffff;
  box-shadow: 0 10px 26px rgba(15, 23, 42, 0.07);
  overflow: hidden;
}

.documents-title {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  padding: 14px 16px;
  border-bottom: 1px solid #e5edf5;
  background: linear-gradient(180deg, #ffffff, #f8fafc);
}

.documents-title svg {
  color: #2563eb;
}

.documents-title h2 {
  margin: 0;
  color: #111827;
  font-size: 0.98rem;
  font-weight: 850;
}

.documents-title > div { min-width: 0; }
.documents-table-panel { position: relative; }
.documents-table-panel > .documents-title .documents-expand-btn {
  flex: 0 0 auto;
  margin-left: auto;
}
.documents-expand-btn {
  width: 30px;
  height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #cbd8e6;
  border-radius: 6px;
  background: #ffffff;
  color: #1e3a5f;
  cursor: pointer;
}
.documents-expand-btn:hover { border-color: #2563eb; background: #eff6ff; color: #2563eb; }
.documents-table-expanded {
  position: fixed;
  z-index: 120;
  top: 5vh;
  left: 50%;
  width: min(1240px, calc(100vw - 32px));
  max-height: 90vh;
  overflow: auto;
  transform: translateX(-50%);
  box-shadow: 0 25px 70px rgba(15, 23, 42, .35);
}
.documents-table-backdrop {
  position: fixed;
  inset: 0;
  z-index: 110;
  border: 0;
  background: rgba(15, 23, 42, .48);
  backdrop-filter: blur(2px);
  cursor: default;
}

.documents-table-wrap {
  overflow-x: auto;
}

.documents-table {
  width: 100%;
  min-width: 780px;
  border-collapse: collapse;
}

.documents-table th,
.documents-table td {
  border-bottom: 1px solid #edf2f7;
  padding: 12px 14px;
  text-align: left;
  vertical-align: middle;
}

.documents-table th {
  background: #f1f5f9;
  color: #5f7089;
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.documents-table td {
  color: #243247;
  font-size: 0.82rem;
  font-weight: 650;
}

.documents-table tr.selected {
  background: #f8fafc;
}

.documents-table strong {
  display: block;
  color: #111827;
  font-size: 0.86rem;
  font-weight: 850;
}

.documents-table span,
.documents-review-list small,
.documents-version-tool small,
.documents-versions small {
  display: block;
  margin-top: 4px;
  color: #64748b;
  font-size: 0.74rem;
  font-weight: 700;
}

.documents-table em,
.documents-review-list em,
.documents-versions em {
  display: inline-flex;
  border-radius: 999px;
  padding: 5px 8px;
  font-size: 0.68rem;
  font-style: normal;
  font-weight: 950;
}

.documents-table em.safe {
  background: #dcfce7;
  color: #166534;
}

.documents-table em.danger,
.documents-review-list em {
  background: #fee2e2;
  color: #991b1b;
}

.documents-detail {
  display: grid;
}

.documents-detail dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin: 0;
  padding: 14px;
}

.documents-detail dl div {
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  padding: 10px;
  background: #f8fafc;
}

.documents-detail dt {
  color: #64748b;
  font-size: 0.68rem;
  font-weight: 950;
  text-transform: uppercase;
}

.documents-detail dd {
  margin: 5px 0 0;
  color: #111827;
  font-size: 0.78rem;
  font-weight: 850;
}

.documents-detail-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  padding: 0 14px 14px;
}
.documents-detail-actions button {
  min-height: 35px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid #cbd5e1;
  border-radius: 7px;
  padding: 7px 8px;
  background: #164e63;
  color: #fff;
  font-size: .72rem;
  font-weight: 850;
  cursor: pointer;
}
.documents-detail-actions button:hover { filter: brightness(1.08); }
.documents-detail-actions button:nth-child(2) { background: #2563eb; }
.documents-detail-actions button:nth-child(3) { background: #0f766e; }
.documents-detail-actions button:nth-child(4) { background: #7c3aed; }
.documents-detail-actions button:nth-child(5) { background: #b45309; }
.documents-detail-actions button:nth-child(6) { background: #475569; }

.documents-version-tool {
  display: grid;
  gap: 10px;
  padding: 0 14px 14px;
}

.documents-version-tool label {
  display: grid;
  gap: 7px;
  color: #334155;
  font-size: 0.76rem;
  font-weight: 900;
}

.documents-version-tool input,
.documents-modal-form input,
.documents-modal-form select,
.documents-modal-form textarea {
  width: 100%;
  min-height: 40px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  padding: 10px 11px;
  background: #ffffff;
  color: #0f172a;
  font-size: 0.86rem;
  font-weight: 650;
  outline: none;
}

.documents-version-tool input:focus,
.documents-modal-form input:focus,
.documents-modal-form select:focus,
.documents-modal-form textarea:focus {
  border-color: #16a34a;
  box-shadow: 0 0 0 3px rgba(22, 163, 74, 0.12);
}

.documents-modal-form textarea {
  min-height: 92px;
  padding-top: 10px;
  resize: vertical;
}

.documents-versions,
.documents-review-list {
  display: grid;
  gap: 10px;
  padding: 14px;
}

.documents-versions article,
.documents-review-list article {
  border: 1px solid #dbe5ee;
  border-left: 4px solid #2563eb;
  border-radius: 10px;
  padding: 11px;
  background: #ffffff;
}

.documents-versions span,
.documents-review-list span {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.documents-versions strong,
.documents-review-list strong {
  color: #111827;
  font-size: 0.84rem;
  font-weight: 950;
}

.documents-review-list div {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 10px;
}

.documents-review-list button.danger,
.documents-modal-form footer button.danger {
  border-color: #dc2626;
  background: #dc2626;
  color: #ffffff;
}

/* Document forms intentionally use square corners for a consistent record-entry surface. */
.documents-page .documents-modal,
.documents-page .documents-modal header button,
.documents-page .documents-modal-form label,
.documents-page .documents-modal-form input,
.documents-page .documents-modal-form select,
.documents-page .documents-modal-form textarea,
.documents-page .documents-modal-form footer button,
.documents-page .documents-version-tool input,
.documents-page .documents-version-tool button {
  border-radius: 0 !important;
}

.documents-empty {
  min-height: 112px;
  display: grid;
  place-items: center;
  border: 1px dashed #c7d4e3;
  border-radius: 10px;
  color: #64748b;
  font-size: 0.8rem;
  font-weight: 850;
  text-align: center;
}

.documents-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 22px;
  background: rgba(15, 23, 42, 0.5);
  backdrop-filter: blur(7px);
}

.documents-modal {
  width: min(920px, calc(100vw - 30px));
  max-height: calc(100dvh - 34px);
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(226, 232, 240, 0.92);
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 30px 80px rgba(15, 23, 42, 0.28);
  overflow: hidden;
}

.documents-modal.small {
  width: min(560px, 100%);
}

.documents-modal header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 20px;
  color: #ffffff;
  background: linear-gradient(135deg, #0f172a, #065f46, #16a34a);
}

.documents-modal.is-blue header {
  background: linear-gradient(135deg, #0f172a, #1e3a8a, #2563eb);
}

.documents-modal.is-red header {
  background: linear-gradient(135deg, #0f172a, #7f1d1d, #dc2626);
}

.documents-modal header h2 {
  margin: 4px 0 0;
  color: #ffffff;
  font-size: 1.12rem;
  font-weight: 900;
}

.documents-modal header button {
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border: 1px solid rgba(254, 202, 202, 0.92);
  border-radius: 10px;
  background: #dc2626;
  color: #ffffff;
  cursor: pointer;
}

.documents-modal-form {
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  overflow-y: auto;
  padding: 18px 20px;
  background: #ffffff;
}

.documents-modal-form.single {
  grid-template-columns: 1fr;
}

.documents-modal-form label {
  display: grid;
  gap: 7px;
  min-width: 0;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #16a34a;
  border-radius: 10px;
  padding: 11px;
  background: #ffffff;
  color: #334155;
  font-size: 0.78rem;
  font-weight: 850;
}

.documents-modal-form label span {
  color: #334155;
  font-size: 0.78rem;
  font-weight: 900;
}

.documents-modal-form label.wide,
.documents-modal-form footer,
.documents-modal-form p {
  grid-column: 1 / -1;
}
.documents-modal-form .checkbox-line {
  display: flex;
  grid-column: 1 / -1;
  align-items: center;
  gap: 8px;
  border: 0;
  padding: 0;
  background: transparent;
}
.documents-modal-form .checkbox-line input { width: 16px; min-height: 16px; }

.documents-modal-form p {
  margin: 0;
  color: #475569;
  font-size: 0.82rem;
  font-weight: 700;
  line-height: 1.5;
}

.documents-modal-form footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 2px;
  padding-top: 4px;
  border-top: 0;
}

.documents-modal-form footer button:first-child {
  background: #64748b;
  color: #ffffff;
  border-color: transparent;
}

.documents-modal.is-blue .documents-modal-form footer button:last-child {
