  box-shadow: 0 32px 90px rgba(15, 23, 42, 0.2);
}
.setup-landing-header {
  grid-template-columns: 190px minmax(0, 1fr) auto;
  align-items: start;
  gap: 28px;
  margin-bottom: 26px;
}
.setup-brand-lockup { display: grid; gap: 9px; }
.setup-brand-lockup .auth-title-logo { width: 150px; margin: 0; }
.setup-brand-lockup span { color: #64748b; font-size: .7rem; font-weight: 800; line-height: 1.35; }
.setup-heading-copy { min-width: 0; }
.setup-heading-copy h1 { margin: 4px 0 0; color: #0f172a; font-size: clamp(1.35rem, 2.1vw, 1.9rem); line-height: 1.15; font-weight: 900; letter-spacing: -.025em; }
.setup-verified-badge { display: inline-flex; align-items: center; gap: 8px; padding: 9px 12px; color: #075e54; background: #e6f7f3; border: 1px solid #b7e5dc; border-radius: 7px; font-size: .76rem; font-weight: 900; white-space: nowrap; }
.setup-workspace { display: grid; grid-template-columns: 280px minmax(0, 1fr); gap: 18px; align-items: stretch; }
.setup-step-rail { display: flex; flex-direction: column; min-width: 0; padding: 18px 14px; color: #dbeafe; background: linear-gradient(165deg, #122b52, #0d1c36); border-radius: 12px; box-shadow: 0 18px 36px rgba(15, 23, 42, .15); }
.setup-rail-intro { display: flex; justify-content: space-between; align-items: baseline; padding: 2px 8px 15px; border-bottom: 1px solid rgba(255,255,255,.13); }
.setup-rail-intro span { color: #8fb8df; font-size: .64rem; font-weight: 900; letter-spacing: .14em; }
.setup-rail-intro strong { color: #fff; font-size: 1.1rem; }
.setup-rail-intro i { color: #8fb8df; font-size: .7rem; font-style: normal; }
.setup-step-rail nav { display: grid; gap: 5px; padding-top: 12px; }
.setup-rail-step { width: 100%; display: grid; grid-template-columns: 27px minmax(0,1fr) 18px; align-items: center; gap: 9px; padding: 10px 8px; color: #afc4df; border: 1px solid transparent; border-radius: 7px; background: transparent; text-align: left; cursor: pointer; transition: background .18s ease, border-color .18s ease, transform .18s ease; }
.setup-rail-step:hover { background: rgba(255,255,255,.08); transform: translateX(2px); }
.setup-rail-step.is-active { color: #fff; background: rgba(45, 212, 191, .15); border-color: rgba(94, 234, 212, .45); }
.setup-rail-step.is-complete { color: #b8f3df; }
.setup-step-number { width: 25px; height: 25px; display: inline-flex; align-items: center; justify-content: center; color: #a9c7e8; border: 1px solid rgba(169,199,232,.4); border-radius: 50%; font-size: .7rem; font-weight: 900; }
.is-active .setup-step-number { color: #062b2a; border-color: #5eead4; background: #5eead4; }
.is-complete .setup-step-number { color: #8ff0d4; border-color: #4fd1b5; }
.setup-rail-label { display: grid; gap: 2px; min-width: 0; }
.setup-rail-label b { overflow: hidden; color: inherit; font-size: .78rem; text-overflow: ellipsis; white-space: nowrap; }
.setup-rail-label small { overflow: hidden; color: #8299b7; font-size: .65rem; text-overflow: ellipsis; white-space: nowrap; }
.setup-rail-icon { opacity: .65; }
.setup-rail-footer { display: grid; grid-template-columns: 1fr auto; gap: 7px 10px; margin-top: auto; padding: 16px 8px 2px; color: #8fa6c2; font-size: .68rem; font-weight: 800; }
.setup-rail-footer strong { color: #fff; font-size: .82rem; }
.setup-rail-footer .setup-progress { grid-column: 1 / -1; display: block; width: 100%; min-width: 0; height: 5px; overflow: hidden; border: 0; border-radius: 999px; background: rgba(255,255,255,.14); }
.setup-rail-footer .setup-progress i { background: linear-gradient(90deg, #5eead4, #38bdf8); }
.setup-form-card { min-width: 0; align-content: start; padding: 24px 26px 20px; border-radius: 12px; background: #fff; border: 1px solid #dbe4ee; box-shadow: 0 14px 30px rgba(15,23,42,.07); }
.setup-form-topline { display: flex; justify-content: space-between; gap: 10px; margin-bottom: 18px; color: #64748b; font-size: .67rem; font-weight: 900; letter-spacing: .12em; text-transform: uppercase; }
.setup-form-topline span:last-child { color: #0f766e; letter-spacing: .04em; }
.setup-form-card .setup-panel-heading { padding-bottom: 20px; }
.setup-form-card .setup-panel-icon { background: linear-gradient(145deg, #163b72, #0f766e); border-radius: 9px; box-shadow: 0 8px 18px rgba(15,118,110,.18); }
.setup-form-card .setup-panel-heading h2 { color: #0f172a; font-size: 1.12rem; line-height: 1.25; }
.setup-form-card .setup-panel-heading span { color: #64748b; font-weight: 600; }
.setup-form-card .setup-field-grid { padding-top: 4px; }
.setup-form-card .setup-actions { margin-top: 8px; padding-top: 18px; border-top: 1px solid #e2e8f0; }
.setup-form-card .splash-btn-primary { background: #123b72; box-shadow: 0 8px 18px rgba(18,59,114,.18); }
.setup-form-card .splash-btn-primary:hover { background: #0f766e; }

@media (max-width: 900px) {
  .setup-workspace { grid-template-columns: 1fr; }
  .setup-step-rail nav { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .setup-rail-footer { margin-top: 14px; }
}
@media (max-width: 640px) {
  .setup-landing-shell { width: calc(100vw - 20px); max-height: calc(100vh - 20px); margin: 10px auto; padding: 18px; }
