/* Nursing Administration feedback: a compact, tone-aware toast that stays
   above the workspace and remains readable on both desktop and mobile. */
.nursing-admin-view .module-notice-toast {
  position: fixed;
  top: 24px;
  right: 24px;
  z-index: 500;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 30px;
  align-items: start;
  gap: 11px;
  width: min(430px, calc(100vw - 32px));
  padding: 13px 13px 13px 11px;
  border: 1px solid #d7e0ea;
  border-left: 5px solid var(--notice-color);
  border-radius: 6px;
  background: #ffffff;
  color: #172033;
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.18), 0 3px 9px rgba(15, 23, 42, 0.08);
  animation: nursing-admin-notice-in 220ms ease-out both;
}

.nursing-admin-view .module-notice-toast::before {
  content: "✓";
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #dcfce7;
  color: #15803d;
  font-size: 0.95rem;
  font-weight: 900;
}

.nursing-admin-view .module-notice-toast.is-warning::before {
  content: "!";
  background: #fef3c7;
  color: #b45309;
}

.nursing-admin-view .module-notice-toast.is-error::before {
  content: "×";
  background: #ffe4e6;
  color: #be123c;
}

.nursing-admin-view .module-notice-toast.is-info::before {
  content: "i";
  background: #dbeafe;
  color: #1d4ed8;
  font-family: Georgia, serif;
  font-style: italic;
}

.nursing-admin-view .module-notice-toast strong {
  margin: 1px 0 3px;
  color: #173b65;
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}

.nursing-admin-view .module-notice-toast span {
  display: block;
  color: #475569;
  font-size: 0.83rem;
  font-weight: 700;
  line-height: 1.42;
}

.nursing-admin-view .module-notice-close {
  width: 28px;
  height: 28px;
  display: inline-grid;
  place-items: center;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  background: #f8fafc;
  color: #64748b;
  font-size: 1rem;
  font-weight: 800;
  line-height: 1;
  cursor: pointer;
  transition: background 150ms ease, border-color 150ms ease, color 150ms ease;
}

.nursing-admin-view .module-notice-close:hover,
.nursing-admin-view .module-notice-close:focus-visible {
  border-color: var(--notice-color);
  background: var(--notice-color);
  color: #ffffff;
  outline: none;
}

@keyframes nursing-admin-notice-in {
  from { opacity: 0; transform: translate3d(18px, -8px, 0); }
  to { opacity: 1; transform: translate3d(0, 0, 0); }
}

@media (max-width: 640px) {
  .nursing-admin-view .module-notice-toast {
    top: 12px;
    right: 12px;
    width: calc(100vw - 24px);
  }
}

