/* Consistent table controls for operational module tables. The layer is
   mounted once by AppShell and intentionally leaves existing row actions in
   place. */
.global-table-module-root {
  position: relative;
}

.global-table-wrap {
  position: relative;
}

.global-table-pagination {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-height: 46px;
  margin-top: 10px;
  padding: 8px 2px 0;
  border-top: 1px solid #e2e8f0;
}

.global-table-page-status {
  min-width: 130px;
  color: #64748b;
  font-size: 0.74rem;
  font-weight: 750;
  text-align: center;
}

.global-table-page-btn {
  min-width: 66px;
  min-height: 32px;
  border: 1px solid #b8c9dc;
  border-radius: 4px;
  padding: 6px 10px;
  background: #ffffff;
  color: #174a67;
  font-size: 0.74rem;
  font-weight: 800;
  cursor: pointer;
}

.global-table-page-btn:hover:not(:disabled),
.global-table-page-btn:focus-visible:not(:disabled) {
  border-color: #174a67;
  background: #174a67;
  color: #ffffff;
  outline: none;
}

.global-table-page-btn:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.global-table-expand-btn {
  position: absolute;
  z-index: 5;
  top: 8px;
  right: 8px;
  width: 30px;
  height: 30px;
  display: inline-grid;
  place-items: center;
  padding: 0;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  background: #ffffff;
  color: #1e3a5f;
  font-size: 1.1rem;
  font-weight: 800;
  line-height: 1;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.1);
  transition: background 150ms ease, border-color 150ms ease, color 150ms ease;
}

.global-table-expand-btn:hover,
.global-table-expand-btn:focus-visible {
  border-color: #0f766e;
  background: #0f766e;
  color: #ffffff;
  outline: none;
}

/* Expansion controls are valid only on standalone table surfaces. */
button .global-table-expand-btn,
a .global-table-expand-btn,
[role="button"] .global-table-expand-btn { display: none !important; }

.global-table-wrap tbody tr {
  cursor: pointer;
  transition: background 120ms ease, box-shadow 120ms ease;
}

.global-table-wrap tbody tr:hover,
.global-table-wrap tbody tr.is-global-selected-row {
  background: #eff6ff;
  box-shadow: inset 3px 0 0 #2563eb;
}

.global-table-backdrop {
  position: fixed;
  z-index: 1300;
  inset: 0;
  background: rgba(15, 23, 42, 0.36);
  backdrop-filter: blur(3px);
  pointer-events: none;
  animation: global-table-backdrop-in 120ms ease-out;
}

.global-table-wrap.is-global-expanded {
  position: fixed;
  z-index: 1400;
  top: 76px;
  right: 24px;
  bottom: 24px;
  left: clamp(12px, 18vw, 280px);
  display: block;
  overflow: auto;
  min-height: 220px;
  max-height: none;
  padding: 44px 14px 14px;
  border: 1px solid #b8c9dc;
  border-radius: 4px;
  background: #ffffff;
  box-shadow: 0 24px 70px rgba(15, 23, 42, 0.34);
  animation: global-table-expand-in 140ms ease-out;
}

.global-table-wrap.is-global-expanded .global-table-expand-btn {
  top: 10px;
  right: 10px;
  border-color: #dc2626;
  background: #dc2626;
  color: #ffffff;
  font-size: 1rem;
}

.global-table-wrap.is-global-expanded .pv-table {
  min-width: 760px;
}

@keyframes global-table-backdrop-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes global-table-expand-in {
  from { opacity: 0; transform: translateY(8px) scale(0.99); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@media (max-width: 900px) {
  .global-table-wrap.is-global-expanded {
    top: 60px;
    right: 12px;
    bottom: 12px;
    left: 12px;
  }

  .global-table-wrap.is-global-expanded .pv-table {
    min-width: 680px;
  }
}

