/* HMIS form density: keep modal forms readable on ordinary screens. The fields
   remain unchanged; only the modal width and field flow are normalized. */
.module-modal,
.modal-panel,
.module-form-panel,
.module-form-card,
.homecare-modal,
.md-modal,
.patient-form-modal .patient-form-panel {
  width: min(700px, calc(100vw - 32px)) !important;
  max-width: calc(100vw - 32px) !important;
}

[class*="-form-panel"],
[class*="-modal-panel"] {
  width: min(700px, calc(100vw - 32px)) !important;
  max-width: calc(100vw - 32px) !important;
}

.module-modal-form,
.accounting-modal-form,
.canteen-modal-form,
.cdss-modal-form,
.documents-modal-form,
.feedback-modal-form,
.security-popup-form,
.module-form-grid,
.operations-form-grid,
.fss-form-grid,
.billing-form-grid,
.emr-form-grid,
.nursing-form-grid,
.pos-form-grid,
.biomed-form,
.reports-form,
.exec-form,
.ai-form {
  grid-template-columns: minmax(0, 1fr) !important;
}

[class*="-form-grid"],
[class*="-modal-form"],
.homecare-form,
.md-form-grid,
.patient-form-body .grid {
  grid-template-columns: minmax(0, 1fr) !important;
}

.module-modal-form > *,
.accounting-modal-form > *,
.canteen-modal-form > *,
.cdss-modal-form > *,
.documents-modal-form > *,
.feedback-modal-form > *,
.security-popup-form > *,
.module-form-grid > *,
.operations-form-grid > *,
.fss-form-grid > *,
.billing-form-grid > *,
.emr-form-grid > *,
.nursing-form-grid > *,
.pos-form-grid > *,
.biomed-form > *,
.reports-form > *,
.exec-form > *,
.ai-form > * {
  grid-column: 1 / -1 !important;
}

[class*="-form-grid"] > *,
[class*="-modal-form"] > *,
.homecare-form > *,
.md-form-grid > *,
.patient-form-body .grid > * {
  grid-column: 1 / -1 !important;
}

.module-modal-form,
.module-form-grid,
.operations-form-grid,
.fss-form-grid,
.billing-form-grid,
.emr-form-grid,
.nursing-form-grid,
.pos-form-grid,
.biomed-form,
.reports-form,
.exec-form,
.ai-form {
