}

.module-modal-form .module-modal-footer,
.module-form-grid .module-form-footer,
.module-form-grid .form-actions,
.operations-form-grid .form-actions,
.fss-form-grid .form-actions {
  grid-column: 1 / -1 !important;
}

.module-form-panel .module-form-body,
.module-modal-form,
.modal-panel form,
.module-modal form {
  padding-left: 20px;
  padding-right: 20px;
}

@media (max-width: 720px) {
  .module-modal,
  .modal-panel,
  .module-form-panel,
  .module-form-card,
  .homecare-modal,
  .md-modal,
  .patient-form-modal .patient-form-panel {
    width: calc(100vw - 16px) !important;
    max-width: calc(100vw - 16px) !important;
  }
}

