.ai-chat-brand { display:flex; align-items:center; gap:12px; }.ai-chat-brand > span { width:48px; height:48px; display:grid; place-items:center; border-radius:10px; color:#fff; background:linear-gradient(135deg,#0f766e,#2563eb); }.ai-chat-brand small { color:#64748b; font-size:.64rem; font-weight:900; letter-spacing:.1em; }.ai-chat-brand h1 { margin:3px 0; font-size:1.2rem; }.ai-chat-brand p { margin:0; color:#64748b; font-size:.76rem; }.ai-chat-safety { display:flex; align-items:center; gap:6px; padding:8px 10px; border:1px solid #bbf7d0; border-radius:6px; color:#166534; background:#f0fdf4; font-size:.7rem; font-weight:800; }
.ai-chat-shell { display:flex; flex-direction:column; max-width:1040px; min-height:calc(100vh - 190px); margin:0 auto; border:1px solid #d8e2ee; border-radius:9px; background:#fff; box-shadow:0 12px 30px rgba(15,23,42,.07); overflow:hidden; }.ai-chat-messages { flex:1; display:grid; align-content:start; gap:14px; padding:20px; overflow:auto; }.ai-chat-message { display:flex; align-items:flex-start; gap:10px; max-width:78%; }.ai-chat-message.user { justify-self:end; flex-direction:row-reverse; }.ai-chat-avatar { width:30px; height:30px; flex:0 0 30px; display:grid; place-items:center; border-radius:50%; color:#0f766e; background:#ecfdf5; }.ai-chat-message.user .ai-chat-avatar { color:#1d4ed8; background:#eff6ff; }.ai-chat-message small { color:#64748b; font-size:.66rem; font-weight:850; }.ai-chat-message p { margin:4px 0 0; padding:10px 12px; border:1px solid #e2e8f0; border-radius:4px 10px 10px 10px; color:#334155; background:#f8fafc; white-space:pre-wrap; font-size:.8rem; line-height:1.5; }.ai-chat-message.user p { border-color:#bfdbfe; border-radius:10px 4px 10px 10px; color:#1e3a8a; background:#eff6ff; }.ai-chat-thinking { color:#64748b !important; font-style:italic; }.ai-chat-compose { display:flex; align-items:flex-end; gap:10px; padding:14px; border-top:1px solid #e2e8f0; background:#f8fafc; }.ai-chat-compose textarea { flex:1; resize:vertical; min-height:48px; max-height:140px; border:1px solid #cbd5e1; border-radius:5px; padding:10px; color:#17233d; background:#fff; font:inherit; outline:none; }.ai-chat-compose textarea:focus { border-color:#0f766e; box-shadow:0 0 0 3px rgba(15,118,110,.1); }.ai-chat-compose button { min-height:42px; display:inline-flex; align-items:center; gap:6px; border:0; border-radius:5px; padding:0 15px; color:#fff; background:#0f766e; font-size:.76rem; font-weight:850; cursor:pointer; }.ai-chat-compose button:disabled { opacity:.55; cursor:not-allowed; }.ai-chat-disclaimer { display:flex; align-items:center; gap:6px; margin:0; padding:0 14px 12px; color:#64748b; font-size:.68rem; }
@media (max-width:640px) { .ai-chat-page { padding:14px; }.ai-chat-header { align-items:flex-start; flex-direction:column; }.ai-chat-safety { width:100%; box-sizing:border-box; }.ai-chat-shell { min-height:calc(100vh - 220px); }.ai-chat-message { max-width:94%; }.ai-chat-compose { align-items:stretch; flex-direction:column; }.ai-chat-compose button { justify-content:center; } }

/* Executive dashboard layout repair. Keep the dashboard information-dense on
   desktop while allowing every panel to reflow instead of being clipped or
   stretched on smaller workspaces. */
.exec-page {
  min-width: 0;
  padding: 18px 20px 26px;
  overflow-x: hidden;
}

.exec-header { gap: 14px; margin-bottom: 14px; }
.exec-header h1 { margin-bottom: 5px; font-size: 1.18rem; }
.exec-header p { max-width: 720px; font-size: 0.78rem; }
.exec-actions { flex: 0 0 auto; gap: 7px; }
.exec-btn { min-height: 34px; padding: 7px 10px; font-size: 0.76rem; }

.exec-filter { gap: 8px; margin-bottom: 12px; padding: 9px 11px; border-radius: 9px; }
.exec-filter label { min-height: 36px; padding: 0 9px; border-radius: 7px; }
.exec-filter input,
.exec-filter select,
.exec-filter > input { min-height: 34px; font-size: 0.77rem; }
.exec-search { flex-basis: 280px; min-width: min(280px, 100%); }

.exec-stats { gap: 10px; margin-bottom: 12px; }
.exec-stat { min-height: 66px; gap: 9px; border-radius: 8px; padding: 11px 12px; }
.exec-stat span { margin-bottom: 5px; font-size: 0.67rem; }
.exec-stat strong { font-size: 1.05rem; }
.exec-stat i { width: 29px; height: 29px; border-radius: 7px; }

.exec-widget-grid { gap: 10px; }
.exec-widget { min-height: 148px; gap: 9px; border-radius: 9px; padding: 12px; }
.exec-widget h2 { font-size: 0.84rem; }
.exec-widget > strong { font-size: 1.35rem; }
.exec-widget p { font-size: 0.7rem; }
.exec-widget footer button { min-height: 27px; padding: 4px 7px; font-size: 0.68rem; }

.exec-lower { gap: 12px; margin-top: 12px; }
.exec-panel { border-radius: 9px; }
.exec-panel > header { padding: 11px 13px; }
.exec-panel h2 { font-size: 0.88rem; }
.exec-pie-layout { min-height: 176px; grid-template-columns: 132px minmax(0, 1fr); gap: 12px; padding: 12px; }
.exec-pie { width: 122px; box-shadow: inset 0 0 0 17px rgba(255, 255, 255, 0.78), 0 8px 20px rgba(15, 23, 42, 0.1); }
.exec-pie strong { font-size: 1.12rem; }
.exec-pie-legend button { min-height: 33px; padding: 6px 8px; font-size: 0.72rem; }
.exec-snapshot { gap: 8px; padding: 11px; }
.exec-snapshot div { border-radius: 8px; padding: 10px; }
.exec-snapshot span { margin: 5px 0 3px; font-size: 0.67rem; }
.exec-snapshot strong { font-size: 0.9rem; }

.exec-table th { padding: 9px 11px; font-size: 0.66rem; }
.exec-table td { padding: 10px 11px; font-size: 0.76rem; }
.exec-table strong { font-size: 0.79rem; }
.exec-table small { font-size: 0.67rem; }

.exec-modal-backdrop { padding: 14px; }
.exec-modal { width: min(680px, calc(100vw - 28px)); }
.exec-modal header { padding: 15px 17px; }
.exec-form { gap: 10px; padding: 14px 17px; }
.exec-form label { padding: 10px; }

@media (max-width: 1180px) {
  .exec-widget-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .exec-widget.medium { grid-column: span 1; }
  .exec-widget.large { grid-column: span 2; }
  .exec-lower { grid-template-columns: 1fr; }
}

@media (max-width: 760px) {
  .exec-page { padding: 14px 12px 20px; }
  .exec-header { flex-direction: column; align-items: stretch; }
  .exec-actions { justify-content: flex-start; }
  .exec-actions .exec-btn { flex: 1 1 auto; }
  .exec-filter { align-items: stretch; }
  .exec-search { flex-basis: 100%; }
  .exec-filter label,
  .exec-filter > input,
  .exec-filter select { flex: 1 1 160px; }
  .exec-widget-grid,
  .exec-stats { grid-template-columns: 1fr; }
  .exec-widget.medium,
  .exec-widget.large { grid-column: span 1; }
  .exec-snapshot { grid-template-columns: 1fr; }
}

@media (max-width: 560px) {
  .exec-pie-layout { grid-template-columns: 1fr; justify-items: center; }
  .exec-pie-legend { width: 100%; }
  .exec-form { grid-template-columns: 1fr; }
  .exec-form footer { margin-inline: -14px; padding-inline: 14px; }
  .exec-detail { grid-template-columns: 1fr; }
  .exec-detail-group { grid-column: auto; }
}
